INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('273fd27a-55fe-5feb-850b-208b24cacb5e', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'fed684c4-735b-500a-85f8-bf99a91029e7', 'a-level', '30.1', '9702 coursebook 30.1 · X-ray imaging and CT', 9, 9, 'An X-ray tube has 120 kV across it. What is the greatest photon energy it can produce, in keV?', NULL, 1, 'numeric'::answer_type, '120', 'keV', false, NULL, false, NULL, 'An electron gains 1 eV per volt: E(max) = 1 × 120 = 120 keV. Mark scheme (1 mark). A1: E(max) = 120 keV.', 1, NULL, NULL),
('05967f05-8f08-531e-99cd-b66cc38759c4', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'fed684c4-735b-500a-85f8-bf99a91029e7', 'a-level', '30.1', '9702 coursebook 30.1 · X-ray imaging and CT', 10, 10, 'Which process produces the continuous spectrum of X-rays in an X-ray tube?', NULL, 1, 'multiple_choice'::answer_type, 'Fast electrons decelerating rapidly in the target', NULL, false, NULL, false, NULL, 'This braking radiation (bremsstrahlung) has a continuous range of photon energies. Mark scheme (1 mark). B1: C (Fast electrons decelerating rapidly in the target).', 1, NULL, NULL),
('a46b9557-b963-54b7-a53f-dda0ee1f55cf', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'fed684c4-735b-500a-85f8-bf99a91029e7', 'a-level', '30.1', '9702 coursebook 30.1 · X-ray imaging and CT', 11, 11, 'Calculate the shortest wavelength of the X-rays from a tube operating at 40 kV, in units of 10⁻¹¹ m. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '3.108', '10⁻¹¹ m', false, NULL, false, NULL, 'λ(min) = hc/eV = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (1.60 × 10⁻¹⁹ × 40 × 10³) = 3.11 × 10⁻¹¹ m. Mark scheme (2 marks). C1: eV = hc/λ(min). A1: λ(min) = 3.11 × 10⁻¹¹ m.', 2, NULL, NULL),
('59f98025-7189-5c78-940e-0980c2d2c051', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'fed684c4-735b-500a-85f8-bf99a91029e7', 'a-level', '30.1', '9702 coursebook 30.1 · X-ray imaging and CT', 12, 12, 'Why is tungsten used for the target of an X-ray tube?', NULL, 1, 'multiple_choice'::answer_type, 'It has a very high melting point and a high proton number', NULL, false, NULL, false, NULL, 'About 99% of the beam energy becomes heat, and high Z gives efficient X-ray production. Mark scheme (1 mark). B1: A (It has a very high melting point and a high proton number).', 1, NULL, NULL),
('8fc3081e-ce9a-5b7e-af70-16b49d7fdaba', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'fed684c4-735b-500a-85f8-bf99a91029e7', 'a-level', '30.1', '9702 coursebook 30.1 · X-ray imaging and CT', 13, 13, 'Electrons in an X-ray tube are accelerated through 30 kV. Calculate the kinetic energy of each electron at the target, in units of 10⁻¹⁵ J. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '4.8', '10⁻¹⁵ J', false, NULL, false, NULL, 'Ek = eV = 1.60 × 10⁻¹⁹ × 30 × 10³ = 4.8 × 10⁻¹⁵ J. Mark scheme (2 marks). C1: Ek = eV. A1: Ek = 4.8 × 10⁻¹⁵ J.', 2, NULL, NULL),
('f93d4047-3c07-5a75-adc2-4c73c41a796e', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'fed684c4-735b-500a-85f8-bf99a91029e7', 'a-level', '30.1', '9702 coursebook 30.1 · X-ray imaging and CT', 14, 14, 'What causes the sharp lines (characteristic X-rays) in an X-ray spectrum?', NULL, 1, 'multiple_choice'::answer_type, 'Electrons in target atoms dropping into vacancies in inner shells', NULL, false, NULL, false, NULL, 'The line energies are set by the target element''s inner-shell levels. Mark scheme (1 mark). B1: D (Electrons in target atoms dropping into vacancies in inner shells).', 1, NULL, NULL),
('95e5244d-4ca3-535c-a560-564e47e71a01', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'fed684c4-735b-500a-85f8-bf99a91029e7', 'a-level', '30.1', '9702 coursebook 30.1 · X-ray imaging and CT', 15, 15, 'An X-ray tube carries a current of 5.0 mA. How many electrons strike the target each second? Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '3.125e16', NULL, false, NULL, false, NULL, 'n = I/e = 5.0 × 10⁻³ ÷ 1.60 × 10⁻¹⁹ = 3.13 × 10¹⁶. Mark scheme (2 marks). C1: n = I/e. A1: n = 3.13 × 10¹⁶.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 440 230" role="img" aria-labelledby="fg31aacf21-t fg31aacf21-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg31aacf21-t">X-ray tube</title><desc id="fg31aacf21-d">An X-ray tube: electrons from the heated cathode cross the vacuum to the tungsten target on the anode; X-rays leave through a window. The tube current is 5.0 mA.</desc><rect x="40" y="50" width="330" height="100" rx="40" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="56" y="62" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">vacuum</text><path d="M80,90 q5,-10 10,0 t10,0 t10,0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="80" y1="90" x2="60" y2="90" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="110" y1="90" x2="120" y2="80" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="95" y="122" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">cathode</text><polygon points="290,70 330,70 330,130 290,110" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="330" y1="100" x2="385" y2="100" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="318" y="58" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">anode (tungsten target)</text><line x1="115" y1="96.4" x2="279.8" y2="89" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="284,88.8 278.7,91.6 278.5,86.5" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="115" y1="100" x2="279.8" y2="96.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="284,96 278.6,98.7 278.5,93.6" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="115" y1="103.6" x2="279.8" y2="103.2" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="284,103.2 278.6,105.7 278.6,100.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="200" y="120" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">electrons</text><line x1="282" y1="106" x2="264.5" y2="203.2" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="263.6,208 261.8,201.2 267.6,202.3" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="296" y1="106" x2="286.5" y2="203.1" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="286,208 283.7,201.4 289.6,202" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="310" y1="106" x2="308.5" y2="203.1" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="308.4,208 305.5,201.6 311.5,201.7" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="262" y1="150" x2="318" y2="150" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="345" y="210" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">X-rays</text><text x="205" y="40" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">tube current 5.0 mA</text></svg>', 'An X-ray tube: electrons from the heated cathode cross the vacuum to the tungsten target on the anode; X-rays leave through a window. The tube current is 5.0 mA.'),
('4a9d0991-36ae-510f-83a3-78d6262f9853', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'fed684c4-735b-500a-85f8-bf99a91029e7', 'a-level', '30.1', '9702 coursebook 30.1 · X-ray imaging and CT', 16, 16, 'Why is the inside of an X-ray tube a vacuum?', NULL, 1, 'multiple_choice'::answer_type, 'So that the electrons are not stopped by collisions with gas molecules', NULL, false, NULL, false, NULL, 'Electrons must reach the target with their full energy. Mark scheme (1 mark). B1: B (So that the electrons are not stopped by collisions with gas molecules).', 1, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 440 230" role="img" aria-labelledby="fg32a7b394-t fg32a7b394-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg32a7b394-t">X-ray tube</title><desc id="fg32a7b394-d">An X-ray tube: a heated cathode, an evacuated glass envelope, an angled tungsten target on the anode and a window through which the X-rays leave.</desc><rect x="40" y="50" width="330" height="100" rx="40" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="56" y="62" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">vacuum</text><path d="M80,90 q5,-10 10,0 t10,0 t10,0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="80" y1="90" x2="60" y2="90" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="110" y1="90" x2="120" y2="80" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="95" y="122" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">cathode</text><polygon points="290,70 330,70 330,130 290,110" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="330" y1="100" x2="385" y2="100" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="318" y="58" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">anode (tungsten target)</text><line x1="115" y1="96.4" x2="279.8" y2="89" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="284,88.8 278.7,91.6 278.5,86.5" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="115" y1="100" x2="279.8" y2="96.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="284,96 278.6,98.7 278.5,93.6" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="115" y1="103.6" x2="279.8" y2="103.2" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="284,103.2 278.6,105.7 278.6,100.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="200" y="120" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">electrons</text><line x1="282" y1="106" x2="264.5" y2="203.2" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="263.6,208 261.8,201.2 267.6,202.3" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="296" y1="106" x2="286.5" y2="203.1" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="286,208 283.7,201.4 289.6,202" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="310" y1="106" x2="308.5" y2="203.1" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="308.4,208 305.5,201.6 311.5,201.7" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="262" y1="150" x2="318" y2="150" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="345" y="210" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">X-rays</text></svg>', 'An X-ray tube: a heated cathode, an evacuated glass envelope, an angled tungsten target on the anode and a window through which the X-rays leave.'),
('1fedda33-f248-50bf-9cda-52fe5aaeeaac', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'fed684c4-735b-500a-85f8-bf99a91029e7', 'a-level', '30.1', '9702 coursebook 30.1 · X-ray imaging and CT', 17, 17, 'An X-ray tube operates at 100 kV with a current of 10 mA. Calculate the electrical power input in kW.', NULL, 1, 'numeric'::answer_type, '1 kW', 'kW', false, NULL, false, NULL, 'P = VI = 100 × 10³ × 10 × 10⁻³ = 1000 W, which is 1000 ÷ 1000 = 1.0 kW. Mark scheme (2 marks). C1: P = VI. A1: P = 1.0 kW.', 2, NULL, NULL),
('a47efa6d-a4bb-5271-8572-c328db7abf37', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'fed684c4-735b-500a-85f8-bf99a91029e7', 'a-level', '30.1', '9702 coursebook 30.1 · X-ray imaging and CT', 18, 18, 'In an X-ray tube, most of the electrons'' kinetic energy becomes', NULL, 1, 'multiple_choice'::answer_type, 'thermal energy in the target', NULL, false, NULL, false, NULL, 'Typically only about 1% becomes X-rays. Mark scheme (1 mark). B1: C (thermal energy in the target).', 1, NULL, NULL),
('0aaa644a-a228-526f-baa5-f2ad202981d5', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'fed684c4-735b-500a-85f8-bf99a91029e7', 'a-level', '30.1', '9702 coursebook 30.1 · X-ray imaging and CT', 19, 19, 'An X-ray tube takes 1000 W of electrical power and is 1.0% efficient at producing X-rays. Calculate the X-ray power.', NULL, 1, 'numeric'::answer_type, '10', 'W', false, NULL, false, NULL, 'P = 0.010 × 1000 = 10 W. Mark scheme (2 marks). C1: efficiency × input. A1: P = 10 W.', 2, NULL, NULL),
('b2a2a107-38e1-516a-b220-4011054edc37', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'fed684c4-735b-500a-85f8-bf99a91029e7', 'a-level', '30.1', '9702 coursebook 30.1 · X-ray imaging and CT', 20, 20, 'Which control on an X-ray machine changes the intensity of the beam without changing the photon energies?', NULL, 1, 'multiple_choice'::answer_type, 'The tube current', NULL, false, NULL, false, NULL, 'More electrons per second give more X-ray photons per second. Mark scheme (1 mark). B1: A (The tube current).', 1, NULL, NULL),
('f8cad284-1046-520b-b234-7c09acdb7c8a', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'fed684c4-735b-500a-85f8-bf99a91029e7', 'a-level', '30.1', '9702 coursebook 30.1 · X-ray imaging and CT', 21, 21, 'Calculate the shortest X-ray wavelength produced at 100 kV, in units of 10⁻¹² m. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '12.43', '10⁻¹² m', false, NULL, false, NULL, 'λ = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (1.60 × 10⁻¹⁹ × 100 × 10³) = 1.24 × 10⁻¹¹ m. Mark scheme (2 marks). C1: λ = hc/eV. A1: λ(min) = 12.4 × 10⁻¹² m.', 2, NULL, NULL),
('0ebd9da1-ef59-5a3d-a7aa-d19f882ce07c', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'fed684c4-735b-500a-85f8-bf99a91029e7', 'a-level', '30.1', '9702 coursebook 30.1 · X-ray imaging and CT', 22, 22, 'What sets the hardness (penetrating power) of an X-ray beam?', NULL, 1, 'multiple_choice'::answer_type, 'The accelerating voltage across the tube', NULL, false, NULL, false, NULL, 'Higher voltage gives higher photon energies. Mark scheme (1 mark). B1: D (The accelerating voltage across the tube).', 1, NULL, NULL),
('6e2a2dc9-645c-52c6-b539-bf12dadc33af', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'fed684c4-735b-500a-85f8-bf99a91029e7', 'a-level', '30.1', '9702 coursebook 30.1 · X-ray imaging and CT', 23, 23, 'An X-ray tube works at 80 kV and 20 mA, and 99% of the input power becomes heat in the anode. Calculate the rate of heat production.', NULL, 1, 'numeric'::answer_type, '1584', 'W', false, NULL, false, NULL, 'P = 0.99 × 80 × 10³ × 20 × 10⁻³ = 1580 W. Mark scheme (2 marks). C1: 99% of VI. A1: P = 1580 W.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 440 230" role="img" aria-labelledby="fgce3852f4-t fgce3852f4-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgce3852f4-t">X-ray tube at 80 kV</title><desc id="fgce3852f4-d">An X-ray tube with 80 kV across it and a tube current of 20 mA; most of the electrons'' energy heats the anode.</desc><rect x="40" y="50" width="330" height="100" rx="40" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="56" y="62" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">vacuum</text><path d="M80,90 q5,-10 10,0 t10,0 t10,0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="80" y1="90" x2="60" y2="90" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="110" y1="90" x2="120" y2="80" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="95" y="122" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">cathode</text><polygon points="290,70 330,70 330,130 290,110" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="330" y1="100" x2="385" y2="100" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="318" y="58" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">anode (tungsten target)</text><line x1="115" y1="96.4" x2="279.8" y2="89" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="284,88.8 278.7,91.6 278.5,86.5" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="115" y1="100" x2="279.8" y2="96.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="284,96 278.6,98.7 278.5,93.6" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="115" y1="103.6" x2="279.8" y2="103.2" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="284,103.2 278.6,105.7 278.6,100.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="200" y="120" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">electrons</text><line x1="282" y1="106" x2="264.5" y2="203.2" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="263.6,208 261.8,201.2 267.6,202.3" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="296" y1="106" x2="286.5" y2="203.1" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="286,208 283.7,201.4 289.6,202" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="310" y1="106" x2="308.5" y2="203.1" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="308.4,208 305.5,201.6 311.5,201.7" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="262" y1="150" x2="318" y2="150" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="345" y="210" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">X-rays</text><text x="205" y="22" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">80 kV</text><line x1="60" y1="90" x2="60" y2="22" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="60" y1="22" x2="160" y2="22" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="250" y1="22" x2="385" y2="22" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="385" y1="22" x2="385" y2="100" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="205" y="40" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">20 mA</text></svg>', 'An X-ray tube with 80 kV across it and a tube current of 20 mA; most of the electrons'' energy heats the anode.'),
('01f0bd8d-f9cf-5698-ae41-d97fb9e132c1', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'fed684c4-735b-500a-85f8-bf99a91029e7', 'a-level', '30.1', '9702 coursebook 30.1 · X-ray imaging and CT', 24, 24, 'Why do bones appear white on an X-ray film or digital image?', NULL, 1, 'multiple_choice'::answer_type, 'Bone absorbs X-rays strongly, so little radiation reaches the detector behind it', NULL, false, NULL, false, NULL, 'Less exposure of the detector gives a lighter area. Mark scheme (1 mark). B1: B (Bone absorbs X-rays strongly, so little radiation reaches the detector behind it).', 1, NULL, NULL),
('9bf12139-a835-5c9f-85e2-899d185502c5', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'fed684c4-735b-500a-85f8-bf99a91029e7', 'a-level', '30.1', '9702 coursebook 30.1 · X-ray imaging and CT', 25, 25, 'Calculate the highest X-ray frequency produced by a tube at 50 kV, in units of 10¹⁹ Hz. Take e = 1.60 × 10⁻¹⁹ C and h = 6.63 × 10⁻³⁴ J s.', NULL, 1, 'numeric'::answer_type, '1.207', '10¹⁹ Hz', false, NULL, false, NULL, 'f = eV/h = 1.60 × 10⁻¹⁹ × 50 × 10³ ÷ 6.63 × 10⁻³⁴ = 1.21 × 10¹⁹ Hz. Mark scheme (1 mark). A1: f(max) = 1.21 × 10¹⁹ Hz.', 1, NULL, NULL),
('5c19184e-ce6f-5a5a-8167-484edeb52b47', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'fed684c4-735b-500a-85f8-bf99a91029e7', 'a-level', '30.1', '9702 coursebook 30.1 · X-ray imaging and CT', 26, 26, 'A dental X-ray tube runs at 25 kV. Calculate the cut-off wavelength of its spectrum, in units of 10⁻¹¹ m. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '4.973', '10⁻¹¹ m', false, NULL, false, NULL, 'λ(min) = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (1.60 × 10⁻¹⁹ × 25 × 10³) = 4.97 × 10⁻¹¹ m. Mark scheme (3 marks). C1: eV = hc/λ. C1: kV to V. A1: λ(min) = 4.97 × 10⁻¹¹ m.', 3, NULL, NULL),
('5f93c510-2383-5675-8428-a6dfb52c135f', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'fed684c4-735b-500a-85f8-bf99a91029e7', 'a-level', '30.1', '9702 coursebook 30.1 · X-ray imaging and CT', 27, 27, 'What tube voltage, in kV, is needed for the X-ray spectrum to extend down to 0.020 nm? Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '62.16 kV', 'kV', false, NULL, false, NULL, 'V = hc/eλ = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (1.60 × 10⁻¹⁹ × 0.020 × 10⁻⁹) = 6.216 × 10⁴ V. In kV: 6.216 × 10⁴ ÷ 10³ = 62.2. Mark scheme (3 marks). C1: V = hc/eλ. C1: nm to m. A1: V = 62.2 kV.', 3, NULL, NULL),
('68674ff4-93cd-5d21-a3a1-595da3a13b07', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'fed684c4-735b-500a-85f8-bf99a91029e7', 'a-level', '30.1', '9702 coursebook 30.1 · X-ray imaging and CT', 28, 28, 'The voltage across an X-ray tube is increased, with the current unchanged. How does the spectrum change?', NULL, 2, 'multiple_choice'::answer_type, 'The minimum wavelength decreases and the intensity increases; the characteristic lines stay at the same wavelengths', NULL, false, NULL, false, NULL, 'λ(min) = hc/eV; line wavelengths depend on the target element. Mark scheme (3 marks). C1: λ(min) falls. C1: lines fixed. A1: C (The minimum wavelength decreases and the intensity increases; the characteristic lines stay at the same wavelengths).', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 280" role="img" aria-labelledby="fg3f69b31f-t fg3f69b31f-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg3f69b31f-t">X-ray spectrum</title><desc id="fg3f69b31f-d">Graph of relative intensity against wavelength for an X-ray tube: a continuous spectrum starting at a cut-off wavelength, with two sharp characteristic lines; a second spectrum (dashed) is for a higher tube voltage.</desc><line x1="24" y1="34" x2="24" y2="232" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="87" y1="34" x2="87" y2="232" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="34" x2="150" y2="232" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="213" y1="34" x2="213" y2="232" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="276" y1="34" x2="276" y2="232" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stro