('389acd18-d978-5559-995d-22bc9ff1b941', '29011314-2c26-5526-a48e-05b0e335d3c0', 'To make the beam harder', 'B', false, 1),
('7d53f4f4-da1f-554e-adca-3bcbf1319cf0', '29011314-2c26-5526-a48e-05b0e335d3c0', 'So that X-rays leave only in the useful direction, protecting staff and the patient', 'C', true, 2),
