('67f9ff8a-66bd-5606-a183-23ce786c70a1', '1c75bc01-4834-5ce6-94a1-3af30e0bb572', 'It does not use X-rays', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('e91ab354-810f-5601-ab5f-efb5d21a6bb7', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 7, 7, 'A lead sheet has a half-value thickness of 0.30 mm. How many half-value thicknesses are there in a 1.2 mm sheet?', NULL, 1, 'numeric'::answer_type, '4', NULL, false, NULL, false, NULL, 'n = 1.2 ÷ 0.30 = 4.0. Mark scheme (2 marks). C1: thickness ÷ x½. A1: n = 4.0.', 2, NULL, NULL),
('45f5924b-0827-5bee-a59e-34ffe3503159', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 8, 8, 'A beam passes through 4 half-value thicknesses of a shield. What percentage of its intensity gets through?', NULL, 1, 'numeric'::answer_type, '6.25', '%', false, NULL, false, NULL, 'Fraction = (1/2)⁴ = 0.0625, so 0.0625 × 100 = 6.25 %. Mark scheme (2 marks). C1: (½)⁴. A1: percentage = 6.25%.', 2, NULL, NULL),
('a2f5d184-c916-5deb-a1c7-e1307905e03c', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 9, 9, 'Two equal thicknesses of a material are placed one after the other in an X-ray beam. Which statement is correct?', NULL, 1, 'multiple_choice'::answer_type, 'Each layer transmits the same fraction of the intensity reaching it', NULL, false, NULL, false, NULL, 'Attenuation removes a constant fraction per thickness. Mark scheme (1 mark). B1: C (Each layer transmits the same fraction of the intensity reaching it).', 1, NULL, NULL),
('fe9500ab-8ab3-51a6-8473-3c1a7c7430cb', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 10, 10, 'For one X-ray beam, soft tissue has μ = 0.18 cm⁻¹. What fraction of the beam''s intensity survives a 2.0 cm layer of tissue?', NULL, 1, 'numeric'::answer_type, '0.6977', NULL, false, NULL, false, NULL, 'I/I₀ = e^(−μx) = e^(−0.18 × 2.0) = 0.698. Mark scheme (2 marks). C1: I = I₀e^(−μx). A1: fraction = 0.698.', 2, NULL, NULL),
('03d0113a-9487-56bb-bb09-afefb4ffed92', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 11, 11, 'What does the linear attenuation coefficient μ of a material measure?', NULL, 1, 'multiple_choice'::answer_type, 'The fraction of the beam''s intensity removed per unit thickness', NULL, false, NULL, false, NULL, 'I = I₀e^(−μx): larger μ means faster attenuation. Mark scheme (1 mark). B1: A (The fraction of the beam''s intensity removed per unit thickness).', 1, NULL, NULL),
('650e9c10-7b96-57d9-a7ed-0aca8e6c96fe', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 12, 12, 'Lead has a linear attenuation coefficient of 0.45 mm⁻¹ for a particular X-ray beam. Calculate its half-value thickness in mm.', NULL, 1, 'numeric'::answer_type, '1.54 mm', 'mm', false, NULL, false, NULL, 'x½ = ln 2 ÷ μ = 0.693 ÷ 0.45 = 1.54 mm. Mark scheme (2 marks). C1: x½ = ln 2/μ. A1: x½ = 1.54 mm.', 2, NULL, NULL),
('fbbae0da-2d55-57d9-939a-b0d30917f8c9', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 13, 13, 'Which unit could be used for the linear attenuation coefficient?', NULL, 1, 'multiple_choice'::answer_type, 'm⁻¹', NULL, false, NULL, false, NULL, 'μx must be dimensionless. Mark scheme (1 mark). B1: D (m⁻¹).', 1, NULL, NULL),
('af47e562-edaf-5a94-976e-0bad4ae3656d', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 14, 14, 'Every 2.5 cm of a plastic halves the intensity of an X-ray beam. Find the linear attenuation coefficient of the plastic in cm⁻¹.', NULL, 1, 'numeric'::answer_type, '0.2773', 'cm⁻¹', false, NULL, false, NULL, 'μ = ln 2 ÷ x½ = 0.693 ÷ 2.5 = 0.277 cm⁻¹. Mark scheme (2 marks). C1: μ = ln 2/x½. A1: μ = 0.277 cm⁻¹.', 2, NULL, NULL),
('15a03d81-13b7-5dec-b89f-c98769299265', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 15, 15, 'How does the intensity of an X-ray beam change as it passes through a uniform material?', NULL, 1, 'multiple_choice'::answer_type, 'It falls exponentially with thickness', NULL, false, NULL, false, NULL, 'Each equal thickness removes the same fraction. Mark scheme (1 mark). B1: B (It falls exponentially with thickness).', 1, NULL, NULL),
('d890ae8e-cf45-5576-9fc2-34520ac3c48e', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 16, 16, 'An X-ray beam of intensity 800 W m⁻² passes through two half-value thicknesses of tissue. Calculate the intensity that emerges.', NULL, 1, 'numeric'::answer_type, '200', 'W m⁻²', false, NULL, false, NULL, 'I = 800 × (1/2)² = 200 W m⁻². Mark scheme (2 marks). C1: halve twice. A1: I = 200 W m⁻².', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fg2b1acea2-t fg2b1acea2-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg2b1acea2-t">Attenuation curve</title><desc id="fg2b1acea2-d">Graph of X-ray intensity against thickness, measured in half-value thicknesses: it starts at 800 W m⁻² and halves for every half-value thickness.</desc><line x1="36.2" y1="34" x2="36.2" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="122.6" y1="34" x2="122.6" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="209.1" y1="34" x2="209.1" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="295.5" y1="34" x2="295.5" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="382" y1="34" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.2" y1="242" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.2" y1="193.1" x2="382" y2="193.1" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.2" y1="144.1" x2="382" y2="144.1" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.2" y1="95.2" x2="382" y2="95.2" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.2" y1="46.2" x2="382" y2="46.2" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.2" y1="242" x2="388" y2="242" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.2" y1="242" x2="36.2" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,242 385.7,245 385.7,239" style="fill:currentColor;stroke:none"/><polygon points="36.2,24 39.1,30.3 33.2,30.3" style="fill:currentColor;stroke:none"/><line x1="36.2" y1="242" x2="36.2" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="36.2" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="122.6" y1="242" x2="122.6" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="122.6" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1</text><line x1="209.1" y1="242" x2="209.1" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="209.1" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2</text><line x1="295.5" y1="242" x2="295.5" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="295.5" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">3</text><line x1="382" y1="242" x2="382" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="382" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4</text><line x1="32.2" y1="242" x2="36.2" y2="242" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="29.2" y="242" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="32.2" y1="193.1" x2="36.2" y2="193.1" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="29.2" y="193.1" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">200</text><line x1="32.2" y1="144.1" x2="36.2" y2="144.1" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="29.2" y="144.1" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">400</text><line x1="32.2" y1="95.2" x2="36.2" y2="95.2" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="29.2" y="95.2" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">600</text><line x1="32.2" y1="46.2" x2="36.2" y2="46.2" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="29.2" y="46.2" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">800</text><text x="209.1" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">thickness / half-value thicknesses</text><text x="32.2" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">I / W m⁻²</text><polyline points="36.2,46.2 37.9,48.9 39.6,51.6 41.3,54.2 43.1,56.8 44.8,59.3 46.5,61.9 48.3