.6,226.5 354.3,226.7 356.1,226.9 357.8,227.1 359.5,227.3 361.2,227.6 363,227.7 364.7,227.9 366.4,228.1 368.2,228.3 369.9,228.5 371.6,228.7 373.4,228.9 375.1,229.1 376.8,229.2 378.5,229.4 380.3,229.6 382,229.8" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'Graph of X-ray intensity against thickness, measured in half-value thicknesses: it starts at 800 W m⁻² and halves for every half-value thickness.'),
('e37473ac-9962-5642-be14-3bdf20d1eea2', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 17, 17, 'Material P has a larger linear attenuation coefficient than material Q for the same X-rays. Which is correct?', NULL, 1, 'multiple_choice'::answer_type, 'P absorbs the beam more strongly, so its half-value thickness is smaller', NULL, false, NULL, false, NULL, 'x½ = ln 2/μ, so a larger μ means stronger absorption and a thinner half-value layer. Mark scheme (1 mark). B1: C (P absorbs the beam more strongly, so its half-value thickness is smaller).', 1, NULL, NULL),
('2b68c68b-2629-5bb2-8962-85aedf19fbcd', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 18, 18, 'Express a linear attenuation coefficient of 0.30 cm⁻¹ in m⁻¹.', NULL, 1, 'numeric'::answer_type, '30', 'm⁻¹', false, NULL, false, NULL, 'μ = 0.30 × 100 = 30 m⁻¹. Mark scheme (2 marks). C1: 1 cm⁻¹ = 100 m⁻¹. A1: μ = 30 m⁻¹.', 2, NULL, NULL),
('5c89a15a-b811-5e17-bb47-579bdf4b994d', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 19, 19, 'Why does bone show up clearly on an X-ray image of a limb?', NULL, 1, 'multiple_choice'::answer_type, 'Its attenuation coefficient is much larger than that of soft tissue', NULL, false, NULL, false, NULL, 'The contrast comes from the difference in μ. Mark scheme (1 mark). B1: A (Its attenuation coefficient is much larger than that of soft tissue).', 1, NULL, NULL),
('5cb4b9dc-029f-5e9e-afe5-46a629ac9aba', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 20, 20, 'An X-ray beam passes through 2.0 mm of a material with μ = 1.2 mm⁻¹. What fraction of the intensity gets through?', NULL, 1, 'numeric'::answer_type, '0.09072', NULL, false, NULL, false, NULL, 'I/I₀ = e^(−1.2 × 2.0) = 0.0907. Mark scheme (2 marks). C1: e^(−μx). A1: fraction = 0.0907.', 2, NULL, NULL),
('d200b846-36bd-5032-b73e-95ba0ad8d155', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 21, 21, 'What is the half-value thickness of a material for an X-ray beam?', NULL, 1, 'multiple_choice'::answer_type, 'The thickness that reduces the beam intensity to half', NULL, false, NULL, false, NULL, 'Putting I = I₀/2 into I = I₀e^(−μx) gives x½ = ln 2/μ. Mark scheme (1 mark). B1: D (The thickness that reduces the beam intensity to half).', 1, NULL, NULL),
('298e356c-65e1-5838-a58a-ab807fdf3489', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 22, 22, 'A filter has a half-value thickness of 4.0 mm. What fraction of the beam intensity passes through 12 mm of it?', NULL, 1, 'numeric'::answer_type, '0.125', NULL, false, NULL, false, NULL, '12 ÷ 4.0 = 3 half-value thicknesses: fraction = (1/2)³ = 0.125. Mark scheme (2 marks). C1: three halvings. A1: fraction = 0.125.', 2, NULL, NULL),
('858a35f7-e2a6-57bb-abd1-ac195925366f', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 23, 23, 'In which unit is the intensity of an X-ray beam measured?', NULL, 1, 'multiple_choice'::answer_type, 'W m⁻²', NULL, false, NULL, false, NULL, 'Intensity is power per unit area. Mark scheme (1 mark). B1: B (W m⁻²).', 1, NULL, NULL),
('df7095cd-954f-5598-b06d-5436983d2aa6', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 24, 24, 'A beam of intensity 50 W m⁻² enters a material with μ = 20 m⁻¹. Calculate the intensity after 0.050 m.', NULL, 1, 'numeric'::answer_type, '18.39', 'W m⁻²', false, NULL, false, NULL, 'I = 50 × e^(−20 × 0.050) = 18.4 W m⁻². Mark scheme (2 marks). C1: I = I₀e^(−μx). A1: I = 18.4 W m⁻².', 2, NULL, NULL),
('89d1cf68-076e-5809-b46b-2c9dac960a77', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 25, 25, 'A material has μ = 0.693 cm⁻¹. What thickness, in cm, reduces a beam to one quarter of its intensity?', NULL, 1, 'numeric'::answer_type, '2 cm', 'cm', false, NULL, false, NULL, 'x½ = 0.693 ÷ 0.693 = 1.0 cm; one quarter needs two half-value thicknesses: x = 2 × 1.0 = 2.0 cm. Mark scheme (2 marks). C1: x½ then two of them. A1: x = 2.0 cm.', 2, NULL, NULL),
('3defb1d9-34de-5991-80ef-20012120943e', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 26, 26, 'What percentage of an X-ray beam passes through one half-value thickness of a material?', NULL, 1, 'numeric'::answer_type, '50', '%', false, NULL, false, NULL, 'By definition the intensity halves: 0.5 × 100 = 50 %. Mark scheme (1 mark). A1: percentage = 50%.', 1, NULL, NULL),
('f234b8e7-e048-51bb-b6ba-f5dd2cd0a6a5', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 27, 27, 'Soft tissue has μ = 0.25 cm⁻¹ for an X-ray beam. What thickness reduces the beam to 10% of its intensity?', NULL, 2, 'numeric'::answer_type, '9.21 cm', 'cm', false, NULL, false, NULL, '0.10 = e^(−0.25x), so x = ln 10 ÷ 0.25 = 9.21 cm. Mark scheme (3 marks). C1: equation. C1: take logs. A1: x = 9.21 cm.', 3, NULL, NULL),
('a94f2998-c2c4-5c1b-9771-51a1aa9d1922', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 28, 28, 'An X-ray beam keeps 40% of its intensity after passing through 3.0 cm of a material. Calculate μ in cm⁻¹.', NULL, 2, 'numeric'::answer_type, '0.3054', 'cm⁻¹', false, NULL, false, NULL, '0.40 = e^(−3.0μ), so μ = ln(1 ÷ 0.40) ÷ 3.0 = 0.305 cm⁻¹. Mark scheme (3 marks). C1: equation. C1: take logs. A1: μ = 0.305 cm⁻¹.', 3, NULL, NULL),
('cceb732d-1ccc-51d0-9674-c7e1e2a39544', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 29, 29, 'Calculate (intensity after 1.0 cm of bone, μ = 3.0 cm⁻¹) ÷ (intensity after 1.0 cm of soft tissue, μ = 0.20 cm⁻¹), for the same incident beam.', NULL, 2, 'numeric'::answer_type, '0.06081', NULL, false, NULL, false, NULL, 'Ratio = e^(−3.0) ÷ e^(−0.20) = e^(−2.8) = 0.0608. Mark scheme (3 marks). C1: both transmitted fractions. C1: ratio. A1: ratio = 0.0608.', 3, NULL, NULL),
('29be613f-9562-54ea-967a-3920c8c9ef42', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 30, 30, 'What gives the contrast between bone and soft tissue on an X-ray image?', NULL, 2, 'multiple_choice'::answer_type, 'The large difference between their linear attenuation coefficients', NULL, false, NULL, false, NULL, 'Different μ give different transmitted intensities. Mark scheme (3 marks). C1: different μ. C1: different transmitted intensities. A1: C (The large difference between their linear attenuation coefficients).', 3, NULL, NULL),
('0f97382a-a575-5f48-affd-5da23a42ff60', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 31, 31, 'Lead has μ = 5.5 mm⁻¹ for a beam. What thickness of lead in an apron, in mm, cuts the intensity to 1.0%?', NULL, 2, 'numeric'::answer_type, '0.8373 mm', 'mm', false, NULL, false, NULL, '0.010 = e^(−5.5x), so x = ln 100 ÷ 5.5 = 0.837 mm. Mark scheme (4 marks). C1: fraction 0.010. C1: take logs. C1: value. A1: x = 0.837 mm.', 4, NULL, NULL),
('b4543063-fc1e-5e28-9164-8c07f87a8098', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 32, 32, 'An X-ray beam passes through 3.0 cm of soft tissue (μ = 0.20 cm⁻¹) and then 1.0 cm of bone (μ = 0.60 cm⁻¹). What fraction of the intensity emerges?', NULL, 2, 'numeric'::answer_type, '0.3012', NULL, false, NULL, false, NULL, 'Fraction = e^(−0.20 × 3.0 − 0.60 × 1.0) = e^(−1.2) = 0.301. Mark scheme (3 marks). C1: add the μx terms. C1: value. A1: fraction = 0.301.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 440 200" role="img" aria-labelledby="fge3d00030-t fge3d00030-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fge3d00030-t">Tissue then bone</title><desc id="fge3d00030-d">An X-ray beam of intensity I₀ crossing 3.0 cm of soft tissue (μ = 0.20 cm⁻¹) and then 1.0 cm of bone (μ = 0.60 cm⁻¹).</desc><line x1="14" y1="95" x2="59.7" y2="95" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="66,95 57.8,98.8 57.8,91.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="14" y="79" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">I₀</text><rect x="70" y="50" width="150" height="90" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="145" y="36" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">soft tissue</text><text x="145" y="158" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">3.0 cm</text><rect x="220" y="50" width="50" height="90" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-muted,#6b7280);stroke-linecap:round;stroke-linejoin:round"/><text x="245" y="36" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">bone</text><text x="245" y="158" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.0 cm</text><line x1="274" y1="95" x2="313.7" y2="95" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="320,95 311.8,98.8 311.8,91.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="326" y="95" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">I</text></svg>', 'An X-ray beam of intensity I₀ crossing 3.0 cm of soft tissue (μ = 0.20 cm⁻¹) and then 1.0 cm of bone (μ = 0.60 cm⁻¹).'),
('a08e03b9-4ca8-5a93-a202-6319491bef4f', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 33, 33, 'On which factors does the linear attenuation coefficient of a material depend?', NULL, 2, 'multiple_choice'::answer_type, 'The material (its density and proton number) and the X-ray photon energy', NULL, false, NULL, false, NULL, 'μ is a property of the material for a given photon energy. Mark scheme (3 marks). C1: material. C1: photon energy. A1: A (The material (its density and proton number) and the X-ray photon energy).', 3, NULL, NULL),
('d0260f4b-07b1-5e72-943c-d43267d2ba77', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 34, 34, 'Muscle has a linear attenuation coefficient of 25 m⁻¹ for a beam. Calculate its half-value thickness in mm.', NULL, 2, 'numeric'::answer_type, '27.73 mm', 'mm', false, NULL, false, NULL, 'x½ = 0.693 ÷ 25 = 0.02773 m. In mm: 0.02773 × 10³ = 27.7. Mark scheme (3 marks). C1: x½ = ln 2/μ. C1: m to mm. A1: x½ = 27.7 mm.', 3, NULL, NULL),
('561a2249-b194-536f-801c-b7968c2de607', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 35, 35, 'What fraction of the intensity remains after 1.5 half-value thicknesses?', NULL, 2, 'numeric'::answer_type, '0.3536', NULL, false, NULL, false, NULL, 'Fraction = 0.5^1.5 = 0.354. Mark scheme (3 marks). C1: (½)ⁿ. C1: n = 1.5. A1: fraction = 0.354.', 3, NULL, NULL),
('9b2d62db-76d1-55f8-ac69-96ef3ae1b281', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 36, 36, 'How many half-value thicknesses are needed to reduce an X-ray beam to 1/1000 of its intensity?', NULL, 2, 'numeric'::answer_type, '9.966', NULL, false, NULL, false, NULL, '(1/2)ⁿ = 1/1000, so n = ln 1000 ÷ ln 2 = 9.97. Mark scheme (4 marks). M1: (½)ⁿ = 10⁻³. C1: take logs. C1: value. A1: n = 9.97.', 4, NULL, NULL),
('99accde5-5d2f-5855-a1d3-843af781c652', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 37, 37, 'Why are low-energy X-ray photons a problem in a medical beam?', NULL, 2, 'multiple_choice'::answer_type, 'They are absorbed in the patient''s skin and add to the dose without reaching the detector', NULL, false, NULL, false, NULL, 'Soft X-rays have large μ; an aluminium filter removes them first. Mark scheme (3 marks). C1: large μ for low energy. C1: dose without image. A1: D (They are absorbed in the patient''s skin and add to the dose without reaching the detector).', 3, NULL, NULL),
('4795cee1-63af-5e16-ad56-86c83efd134f', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 38, 38, 'Soft tissue has a density of 1.06 g cm⁻³ and a linear attenuation coefficient of 0.21 cm⁻¹. Calculate its mass attenuation coefficient μ/ρ in cm² g⁻¹.', NULL, 2, 'numeric'::answer_type, '0.1981', 'cm² g⁻¹', false, NULL, false, NULL, 'μ/ρ = 0.21 ÷ 1.06 = 0.198 cm² g⁻¹. Mark scheme (3 marks). C1: μ_m = μ/ρ. C1: value. A1: μ/ρ = 0.198 cm² g⁻¹.', 3, NULL, NULL),
('4366a78e-fb55-5bf4-b6a1-0f13f253d939', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 39, 39, 'Bone has a mass attenuation coefficient of 0.050 m² kg⁻¹ and a density of 1900 kg m⁻³. Calculate its linear attenuation coefficient in m⁻¹.', NULL, 2, 'numeric'::answer_type, '95', 'm⁻¹', false, NULL, false, NULL, 'μ = (μ/ρ) × ρ = 0.050 × 1900 = 95 m⁻¹. Mark scheme (3 marks). C1: μ = μ_m ρ. C1: value. A1: μ = 95 m⁻¹.', 3, NULL, NULL),
('f6391764-b125-5133-a025-bd77ce357409', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 40, 40, 'A graph of ln I against thickness x is plotted for an X-ray beam passing through a material. What is its gradient?', NULL, 2, 'multiple_choice'::answer_type, '−μ', NULL, false, NULL, false, NULL, 'Taking logs of I = I₀e^(−μx) gives ln I = ln I₀ − μx, a straight line of gradient −μ. Mark scheme (3 marks). C1: take logs. C1: gradient −μ. A1: B (−μ).', 3, NULL, NULL),
('d777a666-5004-5fa2-af82-65c059970c3f', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 41, 41, 'A graph of ln I against thickness (in cm) has a gradient of −0.35 cm⁻¹. Calculate the half-value thickness in cm.', NULL, 2, 'numeric'::answer_type, '1.98 cm', 'cm', false, NULL, false, NULL, 'μ = 0.35 cm⁻¹. x½ = 0.693 ÷ 0.35 = 1.98 cm. Mark scheme (3 marks). C1: μ from gradient. C1: x½ = ln 2/μ. A1: x½ = 1.98 cm.', 3, NULL, NULL),
('76925104-b7d7-51eb-816e-ada7f2187871', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 42, 42, 'A beam of intensity 1.0 × 10³ W m⁻² passes through 5.0 cm of tissue with μ = 0.15 cm⁻¹. Calculate the emerging intensity.', NULL, 2, 'numeric'::answer_type, '472.4', 'W m⁻²', false, NULL, false, NULL, 'I = 1.0 × 10³ × e^(−0.15 × 5.0) = 472 W m⁻². Mark scheme (3 marks). C1: I = I₀e^(−μx). C1: μx = 0.75. A1: I = 472 W m⁻².', 3, NULL, NULL),
('1fef0f0d-3803-55c4-94fe-17a24dea9bfe', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 43, 43, 'The voltage across an X-ray tube is raised. What happens to the attenuation of the beam in tissue?', NULL, 2, 'multiple_choice'::answer_type, 'It decreases, because higher-energy photons are more penetrating', NULL, false, NULL, false, NULL, 'μ falls as photon energy rises (over the diagnostic range). Mark scheme (3 marks). C1: higher photon energy. C1: smaller μ. A1: C (It decreases, because higher-energy photons are more penetrating).', 3, NULL, NULL),
('c20a6dfa-c485-50c0-bbf0-b1199f3d72ec', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 44, 44, 'What thickness of aluminium (μ = 0.80 cm⁻¹) attenuates a beam as much as 2.0 mm of lead (μ = 50 cm⁻¹)?', NULL, 2, 'numeric'::answer_type, '12.5 cm', 'cm', false, NULL, false, NULL, 'Equal attenuation needs equal μx: x = 50 × 0.20 ÷ 0.80 = 12.5 cm. Mark scheme (4 marks). M1: μ₁x₁ = μ₂x₂. C1: mm to cm. C1: value. A1: x = 12.5 cm.', 4, NULL, NULL),
('536dc957-d4ed-59dc-b266-c416acf2b814', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 45, 45, 'Why is X-ray attenuation in a uniform material exponential?', NULL, 2, 'multiple_choice'::answer_type, 'Each thin layer removes the same fraction of the intensity reaching it', NULL, false, NULL, false, NULL, 'The rate of loss is proportional to the intensity present, dI/dx = −μI, which gives an exponential. Mark scheme (3 marks). C1: constant fraction per layer. C1: gives exponential. A1: A (Each thin layer removes the same fraction of the intensity reaching it).', 3, NULL, NULL),
('35f2bf87-34e8-5fcb-a8db-f74121a5f201', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 46, 46, 'A beam crosses a limb along two paths: path A through 6.0 cm of soft tissue (μ = 0.20 cm⁻¹), and path B through 4.0 cm of soft tissue and 2.0 cm of bone (μ = 0.60 cm⁻¹). (a) Calculate the fraction transmitted along A. (b) Calculate the fraction along B. (c) Calculate (intensity along A) ÷ (intensity along B).', NULL, 3, 'numeric'::answer_type, '2.226', NULL, false, NULL, false, NULL, '(a) e^(−0.20 × 6.0) = 0.3012. (b) e^(−0.20 × 4.0 − 0.60 × 2.0) = 0.1353. (c) 0.3012 ÷ 0.1353 = 2.23. Mark scheme (5 marks). C1: path A. C1: path B. M1: ratio. C1: value. A1: ratio = 2.23.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 440 200" role="img" aria-labelledby="fg4bd83603-t fg4bd83603-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg4bd83603-t">Path B through a limb</title><desc id="fg4bd83603-d">Path B through the limb: 4.0 cm of soft tissue (μ = 0.20 cm⁻¹) and 2.0 cm of bone (μ = 0.60 cm⁻¹); path A is 6.0 cm of soft tissue only.</desc><line x1="14" y1="95" x2="59.7" y2="95" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="66,95 57.8,98.8 57.8,91.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="14" y="79" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">I₀</text><rect x="70" y="50" width="100" height="90" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="120" y="36" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">soft tissue</text><text x="120" y="158" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.0 cm</text><rect x="170" y="50" width="100" height="90" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-muted,#6b7280);stroke-linecap:round;stroke-linejoin:round"/><text x="220" y="36" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">bone</text><text x="220" y="158" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.0 cm</text><rect x="270" y="50" width="100" height="90" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="320" y="36" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">soft tissue</text><text x="320" y="158" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.0 cm</text><line x1="374" y1="95" x2="413.7" y2="95" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="420,95 411.8,98.8 411.8,91.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="426" y="95" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">I</text></svg>', 'Path B through the limb: 4.0 cm of soft tissue (μ = 0.20 cm⁻¹) and 2.0 cm of bone (μ = 0.60 cm⁻¹); path A is 6.0 cm of soft tissue only.'),
('2e934f50-de50-580d-b4e2-d3860ac209f9', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 47, 47, 'A wall must reduce the X-ray intensity in the next room to 0.10% of its value. Concrete has a half-value thickness of 2.4 cm for this beam. (a) Calculate μ for concrete. (b) Calculate the thickness of concrete needed, in cm.', NULL, 3, 'numeric'::answer_type, '23.92 cm', 'cm', false, NULL, false, NULL, '(a) μ = 0.693 ÷ 2.4 = 0.2888 cm⁻¹. (b) 0.0010 = e^(−μx), so x = ln 1000 ÷ 0.2888 = 23.9 cm. Mark scheme (6 marks). C1: μ. C1: fraction 0.0010. M1: take logs. C1: substitution. C1: value. A1: x = 23.9 cm.', 6, NULL, NULL),
('ed780bf5-75fc-5395-af8a-7c20360b3fbd', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 48, 48, 'An X-ray beam has intensities of 60 W m⁻² after 2.0 cm of a material and 15 W m⁻² after 5.0 cm. (a) Calculate μ. (b) Calculate the incident intensity.', NULL, 3, 'numeric'::answer_type, '151.2', 'W m⁻²', false, NULL, false, NULL, '(a) 15 ÷ 60 = e^(−3.0μ), so μ = ln 4 ÷ 3.0 = 0.4621 cm⁻¹. (b) I₀ = 60 × e^(0.4621 × 2.0) = 151 W m⁻². Mark scheme (5 marks). M1: ratio of intensities. C1: μ. M1: back to x = 0. C1: value. A1: I₀ = 151 W m⁻².', 5, NULL, NULL),
('fc8a90a1-5638-598c-bb93-115187c28acb', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 49, 49, 'An X-ray beam is measured through layers of aluminium: x = 0, 2.0, 4.0, 6.0 mm gives I = 100, 62, 38, 24 units. (a) Explain why ln I should be plotted against x. (b) Use the first and last values to find μ. (c) Calculate the half-value thickness in mm. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '2.914 mm', 'mm', false, NULL, false, NULL, '(a) ln I = ln I₀ − μx is linear. (b) μ = ln(100 ÷ 24) ÷ 6.0 = 0.2379 mm⁻¹. (c) x½ = 0.693 ÷ 0.2379 = 2.91 mm. Mark scheme (6 marks). B1: linear form. C1: ln values. M1: gradient. C1: μ. C1: x½. A1: x½ = 2.91 mm.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 316" role="img" aria-labelledby="fga5dc5f13-t fga5dc5f13-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fga5dc5f13-t">Attenuation by aluminium</title><desc id="fga5dc5f13-d">Table and graph of beam intensity against aluminium thickness: 100, 62, 38 and 24 units at 0, 2.0, 4.0 and 6.0 mm, falling exponentially.</desc><g transform="translate(0,0)"><rect x="74.5" y="8" width="251" height="56" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="74.5" y="8" width="251" height="28" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="110.4" y="22" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">x / mm</text><text x="170.1" y="22" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">0.0</text><line x1="146.4" y1="8" x2="146.4" y2="64" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="215.8" y="22" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">2.0</text><line x1="193.9" y1="8" x2="193.9" y2="64" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="259.7" y="22" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">4.0</text><line x1="237.8" y1="8" x2="237.8" y2="64" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="303.6" y="22" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">6.0</text><line x1="281.6" y1="8" x2="281.6" y2="64" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="74.5" y1="36" x2="325.5" y2="36" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="110.4" y="50" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">I</text><text x="170.1" y="50" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">100</text><text x="215.8" y="50" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">62</text><text x="259.7" y="50" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">38</text><text x="303.6" y="50" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">24</text></g><g transform="translate(0,76)"><line x1="36.2" y1="34" x2="36.2" y2="192" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="135" y1="34" x2="135" y2="192" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="233.8" y1="34" x2="233.8" y2="192" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="332.6" y1="34" x2="332.6" y2="192" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.2" y1="192" x2="382" y2="192" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.2" y1="156.1" x2="382" y2="156.1" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.2" y1="120.2" x2="382" y2="120.2" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.2" y1="84.3" x2="382" y2="84.3" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.2" y1="48.4" x2="382" y2="48.4" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.2" y1="192" x2="388" y2="192" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="36.2" y1="192" x2="36.2" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,192 385.7,195 385.7,189" style="fill:currentColor;stroke:none"/><polygon points="36.2,24 39.1,30.3 33.2,30.3" style="fill:currentColor;stroke:none"/><line x1="36.2" y1="192" x2="36.2" y2="196" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="36.2" y="204" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="135" y1="192" x2="135" y2="196" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="135" y="204" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2</text><line x1="233.8" y1="192" x2="233.8" y2="196" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="233.8" y="204" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4</text><line x1="332.6" y1="192" x2="332.6" y2="196" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="332.6" y="204" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">6</text><line x1="32.2" y1="192" x2="36.2" y2="192" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="29.2" y="192" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="32.2" y1="156.1" x2="36.2" y2="156.1" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="29.2" y="156.1" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">25</text><line x1="32.2" y1="120.2" x2="36.2" y2="120.2" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="29.2" y="120.2" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">50</text><line x1="32.2" y1="84.3" x2="36.2" y2="84.3" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="29.2" y="84.3" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">75</text><line x1="32.2" y1="48.4" x2="36.2" y2="48.4" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="29.2" y="48.4" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">100</text><text x="209.1" y="224" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">x / mm</text><text x="32.2" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">I (arbitrary units)</text><line x1="32.2" y1="44.4" x2="40.2" y2="52.4" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="32.2" y1="52.4" x2="40.2" y2="44.4" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="131" y1="98.9" x2="139" y2="106.9" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="131" y1="106.9" x2="139" y2="98.9" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="229.8" y1="133.4" x2="237.8" y2="141.4" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="229.8" y1="141.4" x2="237.8" y2="133.4" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="328.6" y1="153.5" x2="336.6" y2="161.5" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="328.6" y1="161.5" x2="336.6" y2="153.5" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/></g></svg>', 'Table and graph of beam intensity against aluminium thickness: 100, 62, 38 and 24 units at 0, 2.0, 4.0 and 6.0 mm, falling exponentially.'),
('046b9b4d-ee49-53f0-9303-f17bcd08916e', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 50, 50, 'A beam passes through 4.0 cm of soft tissue (μ = 0.20 cm⁻¹), 1.0 cm of bone (μ = 0.60 cm⁻¹) and another 4.0 cm of soft tissue. (a) Calculate the total μx. (b) Calculate the fraction transmitted.', NULL, 3, 'numeric'::answer_type, '0.1108', NULL, false, NULL, false, NULL, '(a) μx = 0.20 × 8.0 + 0.60 × 1.0 = 2.2. (b) e^(−2.2) = 0.111. Mark scheme (5 marks). C1: tissue total. C1: add bone. M1: e^(−Σμx). C1: value. A1: fraction = 0.111.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 440 200" role="img" aria-labelledby="fg75778813-t fg75778813-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg75778813-t">Three layers</title><desc id="fg75778813-d">An X-ray beam crossing 4.0 cm of soft tissue, 1.0 cm of bone and another 4.0 cm of soft tissue.</desc><line x1="14" y1="95" x2="59.7" y2="95" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="66,95 57.8,98.8 57.8,91.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="14" y="79" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">I₀</text><rect x="70" y="50" width="120" height="90" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="130" y="36" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">soft tissue</text><text x="130" y="158" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4.0 cm</text><rect x="190" y="50" width="40" height="90" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-muted,#6b7280);stroke-linecap:round;stroke-linejoin:round"/><text x="210" y="36" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">bone</text><text x="210" y="158" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.0 cm</text><rect x="230" y="50" width="120" height="90" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="290" y="36" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">soft tissue</text><text x="290" y="158" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4.0 cm</text><line x1="354" y1="95" x2="393.7" y2="95" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="400,95 391.8,98.8 391.8,91.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="406" y="95" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">I</text></svg>', 'An X-ray beam crossing 4.0 cm of soft tissue, 1.0 cm of bone and another 4.0 cm of soft tissue.'),
('d70be9ea-721f-5989-860b-ee86f0e3aaf3', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 51, 51, 'A 2.0 mm aluminium filter has μ = 0.90 mm⁻¹ for 20 keV photons and μ = 0.070 mm⁻¹ for 60 keV photons. (a) Calculate the fraction of each energy transmitted. (b) Calculate (fraction of 20 keV transmitted) ÷ (fraction of 60 keV transmitted). (c) Explain how the filter "hardens" the beam. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.1901', NULL, false, NULL, false, NULL, '(a) 20 keV: e^(−1.8) = 0.1653; 60 keV: e^(−0.14) = 0.8694. (b) 0.1653 ÷ 0.8694 = 0.190. (c) Low-energy photons are removed far more, so the mean photon energy rises. Mark scheme (6 marks). C1: 20 keV fraction. C1: 60 keV fraction. M1: ratio. C1: value. B1: hardening. A1: ratio = 0.190.', 6, NULL, NULL),
('7534bd53-2ab7-5a04-97e6-53cc9b3e6174', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 52, 52, 'A material has a half-value thickness of 3.0 mm. (a) Calculate μ. (b) Calculate the percentage of the intensity transmitted through 10 mm.', NULL, 3, 'numeric'::answer_type, '9.921', '%', false, NULL, false, NULL, '(a) μ = 0.693 ÷ 3.0 = 0.2310 mm⁻¹. (b) e^(−0.2310 × 10) × 100 = 9.92 %. Mark scheme (5 marks). C1: μ. M1: e^(−μx). C1: substitution. C1: value. A1: percentage = 9.92%.', 5, NULL, NULL),
('81ec005a-39a7-5445-933a-faa77b46dd39', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '0f96d95f-3125-445b-b0da-4dd630b4ff15', 'a-level', '30.2', '9702 coursebook 30.2 · X-ray attenuation', 53, 53, 'A patient is 4.0 cm thicker than average. Tissue has μ = 0.20 cm⁻¹. (a) Calculate the extra attenuation factor e^(μΔx). (b) By what factor must the exposure (mA s) be increased to give the same detector intensity? (c) State one disadvantage. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '2.226', NULL, false, NULL, false, NULL, '(a) e^(0.20 × 4.0) = 2.23. (b) The exposure must rise by the same factor, 2.23. (c) The patient dose is larger. Mark scheme (6 marks). C1: μΔx = 0.80. C1: factor. M1: intensity ∝ exposure. C1: value. B1: higher dose. A1: factor = 2.23.', 6, NULL, NULL)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('24e574b7-ba05-5bac-8e4b-c0b69ab2203d', 'a2f5d184-c916-5deb-a1c7-e1307905e03c', 'Each layer absorbs the same amount of energy per second', 'A', false, 0),
('9cbd2766-b597-5511-ba0f-c23e06785506', 'a2f5d184-c916-5deb-a1c7-e1307905e03c', 'The second layer absorbs nothing', 'B', false, 1),
('6936f763-9b58-58d7-9602-139f82580581', 'a2f5d184-c916-5deb-a1c7-e1307905e03c', 'Each layer transmits the same fraction of the intensity reaching it', 'C', true, 2),
('e53bf88c-3157-5813-b21e-bb54966b4e48', 'a2f5d184-c916-5deb-a1c7-e1307905e03c', 'The first layer absorbs everything', 'D', false, 3),
('f72c0275-5f57-558f-9962-d92495e50ee9', '03d0113a-9487-56bb-bb09-afefb4ffed92', 'The fraction of the beam''s intensity removed per unit thickness', 'A', true, 0),
('7d50e972-6c23-5993-a5cc-15f42e393b48', '03d0113a-9487-56bb-bb09-afefb4ffed92', 'The thickness that stops the beam completely', 'B', false, 1),
('065547da-1a82-5470-8a98-c029a9b5d891', '03d0113a-9487-56bb-bb09-afefb4ffed92', 'The density of the material', 'C', false, 2),
('97669696-900e-5d8c-b28c-b216a380ed93', '03d0113a-9487-56bb-bb09-afefb4ffed92', 'The energy of each X-ray photon', 'D', false, 3),
('a429dfd8-88f8-54e8-b87d-73a3f22afe33', 'fbbae0da-2d55-57d9-939a-b0d30917f8c9', 'm', 'A', false, 0),
('16dfff7b-7c7d-5d6e-a458-a3a557e96080', 'fbbae0da-2d55-57d9-939a-b0d30917f8c9', 'W m⁻²', 'B', false, 1),
('f06aad35-4cfb-5400-b3f6-386dfa4f0e3e', 'fbbae0da-2d55-57d9-939a-b0d30917f8c9', 'kg m⁻³', 'C', false, 2),
('08b58252-29c5-523d-bf55-40ab4bf168f4', 'fbbae0da-2d55-57d9-939a-b0d30917f8c9', 'm⁻¹', 'D', true, 3),
('0c56c6e3-f3a0-5f5a-9c01-5426aa436daa', '15a03d81-13b7-5dec-b89f-c98769299265', 'It falls linearly to zero', 'A', false, 0),
('e30d364e-aa3f-5ac4-a7b7-d3a499a4be1c', '15a03d81-13b7-5dec-b89f-c98769299265', 'It falls exponentially with thickness', 'B', true, 1),
