('996e5f44-30df-5dc3-81ae-f857eee54e36', 'e37473ac-9962-5642-be14-3bdf20d1eea2', 'P has the larger half-value thickness', 'B', false, 1),
('a064ded9-24b8-5b7b-8f8f-4eb1d27a87e6', 'e37473ac-9962-5642-be14-3bdf20d1eea2', 'P absorbs the beam more strongly, so its half-value thickness is smaller', 'C', true, 2),
('c53c2b21-bc6b-5710-a702-1c0dacff32f4', 'e37473ac-9962-5642-be14-3bdf20d1eea2', 'They have the same half-value thickness', 'D', false, 3),
('a17ed4c0-3f8f-531c-8d24-88637257d086', '5c89a15a-b811-5e17-bb47-579bdf4b994d', 'Its attenuation coefficient is much larger than that of soft tissue', 'A', true, 0),
('d2ac2e24-2562-5ade-85ef-aa07d5d58f98', '5c89a15a-b811-5e17-bb47-579bdf4b994d', 'It is thinner than soft tissue', 'B', false, 1),
('81a9af74-06f4-5ba1-bbf9-886bca5aa2ae', '5c89a15a-b811-5e17-bb47-579bdf4b994d', 'It reflects X-rays', 'C', false, 2),
('d6804273-4677-5cc1-922d-d5986c8b37eb', '5c89a15a-b811-5e17-bb47-579bdf4b994d', 'Its attenuation coefficient is smaller than that of soft tissue', 'D', false, 3),
('cfcbbae6-72f3-5593-aeb4-e3c62aa4d402', 'd200b846-36bd-5032-b73e-95ba0ad8d155', 'Half the thickness that stops the beam', 'A', false, 0),
('b4dfff48-dfdd-5942-b426-93129704b763', 'd200b846-36bd-5032-b73e-95ba0ad8d155', 'The thickness of half the patient', 'B', false, 1),
('0cb2b4ff-c747-5087-bb35-d13027bab5f6', 'd200b846-36bd-5032-b73e-95ba0ad8d155', 'The thickness that halves the photon energy', 'C', false, 2),
('a9f82d7d-2419-5989-9a92-8752bfc98eed', 'd200b846-36bd-5032-b73e-95ba0ad8d155', 'The thickness that reduces the beam intensity to half', 'D', true, 3),
('30b12fc9-a19d-59a1-9d69-f0728a7463d2', '858a35f7-e2a6-57bb-abd1-ac195925366f', 'W', 'A', false, 0),
('ae519b16-42da-5e85-94fb-71bac929adc3', '858a35f7-e2a6-57bb-abd1-ac195925366f', 'W m⁻²', 'B', true, 1),
('54cfb2f7-8118-505f-9e4f-d0884992e889', '858a35f7-e2a6-57bb-abd1-ac195925366f', 'J', 'C', false, 2),
('61ab630b-5dda-550d-bf16-96083eaf0327', '858a35f7-e2a6-57bb-abd1-ac195925366f', 'm⁻¹', 'D', false, 3),
('1499135e-d38b-565e-a956-025281992a29', '29be613f-9562-54ea-967a-3920c8c9ef42', 'The difference in their temperatures', 'A', false, 0),
('bcd2d05f-aec7-5f9b-93d6-e44b76e7741d', '29be613f-9562-54ea-967a-3920c8c9ef42', 'The difference in their electrical resistances', 'B', false, 1),
('7323d5d4-8b7b-53cf-a450-e8ef5a5ea8b7', '29be613f-9562-54ea-967a-3920c8c9ef42', 'The large difference between their linear attenuation coefficients', 'C', true, 2),
('6376d492-d6a1-5aa7-9413-b0a8999ba87d', '29be613f-9562-54ea-967a-3920c8c9ef42', 'The fact that bone emits X-rays', 'D', false, 3),
('9965407c-8e92-50e8-bab4-5038ae3cfb4d', 'a08e03b9-4ca8-5a93-a202-6319491bef4f', 'The material (its density and proton number) and the X-ray photon energy', 'A', true, 0),
('7eb63a29-7f72-5449-805c-9c229bd8dd6c', 'a08e03b9-4ca8-5a93-a202-6319491bef4f', 'Only the thickness of the material', 'B', false, 1),
('6c3df427-0a35-522c-9eb9-88773ec4ebfc', 'a08e03b9-4ca8-5a93-a202-6319491bef4f', 'Only the intensity of the beam', 'C', false, 2),
('6e5fa574-fd9b-5e9c-bbd5-cadd9d65762e', 'a08e03b9-4ca8-5a93-a202-6319491bef4f', 'Only the size of the patient', 'D', false, 3),
('830feff4-6798-57af-ba55-a2f40f3147ae', '99accde5-5d2f-5855-a1d3-843af781c652', 'They pass through the patient without being absorbed', 'A', false, 0),
('e8220e81-3f41-5540-a671-39cf62e04df1', '99accde5-5d2f-5855-a1d3-843af781c652', 'They make the image too sharp', 'B', false, 1),
('a84c0119-030d-5080-ae95-423700c8056c', '99accde5-5d2f-5855-a1d3-843af781c652', 'They damage the X-ray tube', 'C', false, 2),
('4e19656b-84f3-5264-ac35-c556f93491c0', '99accde5-5d2f-5855-a1d3-843af781c652', 'They are absorbed in the patient''s skin and add to the dose without reaching the detector', 'D', true, 3),
('0e30f828-2c46-5305-8ac4-5ed72e900b81', 'f6391764-b125-5133-a025-bd77ce357409', 'μ', 'A', false, 0),
('9835bdff-629c-5154-8e31-d6f67fafe958', 'f6391764-b125-5133-a025-bd77ce357409', '−μ', 'B', true, 1),
('ffaf5896-c7a2-5631-8db5-bae8167486d2', 'f6391764-b125-5133-a025-bd77ce357409', 'ln 2/μ', 'C', false, 2),
('bb82228c-db5e-544a-9171-de4f58315f79', 'f6391764-b125-5133-a025-bd77ce357409', '−1/μ', 'D', false, 3),
('a14488c0-9a27-5f5a-97a4-7bba0d28af1f', '1fef0f0d-3803-55c4-94fe-17a24dea9bfe', 'It increases', 'A', false, 0),
('75fa9a81-b662-5ca0-906c-7bc91a4ffb9f', '1fef0f0d-3803-55c4-94fe-17a24dea9bfe', 'It is unchanged', 'B', false, 1),
('35f517be-351b-537b-a14f-f4f3dfcc78ef', '1fef0f0d-3803-55c4-94fe-17a24dea9bfe', 'It decreases, because higher-energy photons are more penetrating', 'C', true, 2),
('30fee0b6-0d81-5309-b9a5-cbb068113672', '1fef0f0d-3803-55c4-94fe-17a24dea9bfe', 'It becomes zero', 'D', false, 3),
('e4aa0bb5-1f9c-5285-919d-3f8c09a20296', '536dc957-d4ed-59dc-b266-c416acf2b814', 'Each thin layer removes the same fraction of the intensity reaching it', 'A', true, 0),
('38f732d9-2b71-5ef2-a523-bcfe2c6497de', '536dc957-d4ed-59dc-b266-c416acf2b814', 'Each layer removes the same amount of intensity', 'B', false, 1),
('0804b476-7d92-5ecb-941c-6d461ee5a601', '536dc957-d4ed-59dc-b266-c416acf2b814', 'The photons slow down as they go', 'C', false, 2),
('0711046f-ecad-51b1-bab4-357fd37a5309', '536dc957-d4ed-59dc-b266-c416acf2b814', 'The photons gain energy', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('75d348b1-43ec-5c66-a785-98e52685b74b', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 7, 7, 'An intensifying screen reduces the exposure time needed by a factor of 25. Without it, the exposure would last 0.50 s. Calculate the exposure time with the screen.', NULL, 1, 'numeric'::answer_type, '0.02', 's', false, NULL, false, NULL, 't = 0.50 ÷ 25 = 0.020 s. Mark scheme (2 marks). C1: divide by the factor. A1: t = 0.020 s.', 2, NULL, NULL),
('69d95ee3-369a-5684-949c-b87125c84fd5', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 8, 8, 'What is meant by the sharpness of an X-ray image?', NULL, 1, 'multiple_choice'::answer_type, 'How clearly the edges of structures are defined', NULL, false, NULL, false, NULL, 'Blurred edges mean poor sharpness. Mark scheme (1 mark). B1: C (How clearly the edges of structures are defined).', 1, NULL, NULL),
('5b0da9fb-b877-562b-b97b-0a32c20509be', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 9, 9, 'An X-ray tube has a focal spot 1.0 mm wide. The object is 0.90 m from the focal spot and 0.10 m from the detector. Calculate the width of the blurred edge (penumbra) in mm, using width = spot size × (object–detector distance ÷ source–object distance).', NULL, 1, 'numeric'::answer_type, '0.1111 mm', 'mm', false, NULL, false, NULL, 'w = 1.0 × 0.10 ÷ 0.90 = 0.111 mm. Mark scheme (2 marks). C1: similar triangles. A1: w = 0.111 mm.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 460 300" role="img" aria-labelledby="fgbedb9555-t fgbedb9555-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgbedb9555-t">Penumbra</title><desc id="fgbedb9555-d">A focal spot 1.0 mm wide, an object edge 0.90 m from the spot and a detector 0.10 m beyond the object; rays from the two sides of the spot give a blurred edge, the penumbra.</desc><rect x="82" y="105" width="16" height="30" rx="0" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="90" y="91" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">focal spot</text><rect x="264" y="70" width="12" height="50" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-muted,#6b7280);stroke-linecap:round;stroke-linejoin:round"/><line x1="370" y1="30" x2="370" y2="250" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="370" y="22" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">detector</text><line x1="90" y1="105" x2="370" y2="128.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:4 3"/><line x1="90" y1="135" x2="370" y2="111.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:4 3"/><line x1="376" y1="111.7" x2="376" y2="128.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="382" y="120" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">penumbra</text><text x="270" y="60" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">object</text><text x="90" y="151" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.0 mm</text><polygon points="90,270 96.3,267 96.3,273" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="94.9" y1="270" x2="265.1" y2="270" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="270,270 263.7,273 263.7,267" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="180" y="282" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.90 m</text><polygon points="270,270 276.3,267 276.3,273" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="274.9" y1="270" x2="365.1" y2="270" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="370,270 363.7,273 363.7,267" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="320" y="282" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.10 m</text></svg>', 'A focal spot 1.0 mm wide, an object edge 0.90 m from the spot and a detector 0.10 m beyond the object; rays from the two sides of the spot give a blurred edge, the penumbra.'),
('1f1202af-ba57-5de2-95e2-9cf6b4de4ac3', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 10, 10, 'How does a smaller focal spot affect an X-ray image?', NULL, 1, 'multiple_choice'::answer_type, 'It makes the image sharper', NULL, false, NULL, false, NULL, 'A point-like source gives a smaller penumbra. Mark scheme (1 mark). B1: A (It makes the image sharper).', 1, NULL, NULL),
('7b96e932-b079-5c27-b56a-1bbaf1b38c5f', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 11, 11, 'The X-ray intensity 1.0 m from a tube is 400 units. Assuming an inverse-square law, calculate the intensity 2.0 m from the tube.', NULL, 1, 'numeric'::answer_type, '100', NULL, false, NULL, false, NULL, 'I ∝ 1/d²: I = 400 × (1.0 ÷ 2.0)² = 100 units. Mark scheme (2 marks). C1: inverse square. A1: I = 100.', 2, NULL, NULL),
('0b4234f3-13b5-5265-a074-a14fc49cd3b0', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 12, 12, 'Which of these is NOT a benefit of collimating an X-ray beam to the area being examined?', NULL, 1, 'multiple_choice'::answer_type, 'It makes each X-ray photon more energetic', NULL, false, NULL, false, NULL, 'Collimation limits the beam area; it does not change photon energy. Mark scheme (1 mark). B1: D (It makes each X-ray photon more energetic).', 1, NULL, NULL),
('fa1b55d9-83df-55b7-9ea1-9a28749a6663', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 13, 13, 'Behind bone 20% of the incident intensity reaches the detector; behind soft tissue 80% does. Calculate the contrast ratio (soft tissue ÷ bone).', NULL, 1, 'numeric'::answer_type, '4', NULL, false, NULL, false, NULL, 'Ratio = 0.80 ÷ 0.20 = 4.0. Mark scheme (2 marks). C1: ratio of intensities. A1: ratio = 4.0.', 2, NULL, NULL),
('c5d7abc7-92b6-50b3-b131-b817e88a9fcc', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 14, 14, 'Why are contrast media such as iodine or barium chosen?', NULL, 1, 'multiple_choice'::answer_type, 'They have high proton numbers, so they attenuate X-rays strongly', NULL, false, NULL, false, NULL, 'Attenuation increases steeply with proton number. Mark scheme (1 mark). B1: B (They have high proton numbers, so they attenuate X-rays strongly).', 1, NULL, NULL),
('d414e790-4f05-5daf-b486-acb979739491', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 15, 15, 'An exposure uses 200 mA for 0.10 s. Calculate the charge that flows, in mC.', NULL, 1, 'numeric'::answer_type, '20 mC', 'mC', false, NULL, false, NULL, 'Q = It = 200 × 10⁻³ × 0.10 = 0.020 C. In mC: 0.020 × 10³ = 20. Mark scheme (2 marks). C1: Q = It. A1: Q = 20 mC.', 2, NULL, NULL),
('4e9d2193-29b8-541a-9382-9d025e603d33', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 16, 16, 'Where is an anti-scatter grid placed?', NULL, 1, 'multiple_choice'::answer_type, 'Between the patient and the detector', NULL, false, NULL, false, NULL, 'It stops scattered X-rays from the patient reaching the detector. Mark scheme (1 mark). B1: C (Between the patient and the detector).', 1, NULL, NULL),
('001fccc1-d1b0-578d-82ad-8a67050fa186', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 17, 17, 'An anti-scatter grid transmits 80% of the primary beam. The primary intensity reaching the grid is 1000 units. Calculate the primary intensity reaching the detector.', NULL, 1, 'numeric'::answer_type, '800', NULL, false, NULL, false, NULL, 'I = 0.80 × 1000 = 800 units. Mark scheme (2 marks). C1: fraction transmitted. A1: I = 800.', 2, NULL, NULL),
('d3ccebc0-2ccd-50ba-864c-9cceaef2eb13', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 18, 18, 'How does scattered radiation affect an X-ray image?', NULL, 1, 'multiple_choice'::answer_type, 'It fogs the image and reduces contrast', NULL, false, NULL, false, NULL, 'Scattered photons arrive from random directions. Mark scheme (1 mark). B1: A (It fogs the image and reduces contrast).', 1, NULL, NULL),
('4964e6fc-b7d8-5082-b911-2b0faf3e2aa2', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 19, 19, 'A radiograph gives a dose of 2.0 mGy with a 0.10 s exposure. Assuming the dose is proportional to exposure time, calculate the dose for a 0.25 s exposure, in mGy.', NULL, 1, 'numeric'::answer_type, '5', 'mGy', false, NULL, false, NULL, 'D = 2.0 × 0.25 ÷ 0.10 = 5.0 mGy. Mark scheme (2 marks). C1: proportional scaling. A1: D = 5.0 mGy.', 2, NULL, NULL),
('82d1c9ec-2fbd-5877-b4c2-97b17616d70d', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 20, 20, 'What is one advantage of a digital X-ray detector over film?', NULL, 1, 'multiple_choice'::answer_type, 'The image can be adjusted and sent electronically straight away', NULL, false, NULL, false, NULL, 'Digital images can be processed, stored and shared at once. Mark scheme (1 mark). B1: D (The image can be adjusted and sent electronically straight away).', 1, NULL, NULL),
('7c1325b1-2473-5b94-8dfa-93a10090f6e2', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 21, 21, 'A digital detector 43 cm wide has 3000 pixels across it. Calculate the width of one pixel in mm.', NULL, 1, 'numeric'::answer_type, '0.1433 mm', 'mm', false, NULL, false, NULL, 'w = 430 ÷ 3000 = 0.143 mm. Mark scheme (2 marks). C1: width ÷ number of pixels. A1: w = 0.143 mm.', 2, NULL, NULL),
('5b79cd56-4920-5d93-9e42-a34bcfe65121', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 22, 22, 'How should the patient be placed relative to the detector for the sharpest image?', NULL, 1, 'multiple_choice'::answer_type, 'As close to the detector as possible', NULL, false, NULL, false, NULL, 'A small object-detector distance reduces the penumbra. Mark scheme (1 mark). B1: B (As close to the detector as possible).', 1, NULL, NULL),
('3d3830be-1f19-5e0e-a337-7f8be01b02d1', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 23, 23, 'Without screens an exposure would take 2.0 s. Screens reduce it by a factor of 40. Calculate the new exposure time.', NULL, 1, 'numeric'::answer_type, '0.05', 's', false, NULL, false, NULL, 't = 2.0 ÷ 40 = 0.050 s. Mark scheme (1 mark). A1: t = 0.050 s.', 1, NULL, NULL),
('0774931a-d279-5af7-b892-8e8798a5133d', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 24, 24, 'A focal spot of 0.80 mm is 1.2 m from an object, which is 0.30 m from the detector. Calculate the penumbra width in mm.', NULL, 2, 'numeric'::answer_type, '0.2 mm', 'mm', false, NULL, false, NULL, 'w = 0.80 × 0.30 ÷ 1.2 = 0.20 mm. Mark scheme (3 marks). C1: similar triangles. C1: substitution. A1: w = 0.20 mm.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 460 300" role="img" aria-labelledby="fg8615c072-t fg8615c072-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg8615c072-t">Penumbra</title><desc id="fg8615c072-d">A focal spot 0.80 mm wide 1.2 m from an object, which is 0.30 m from the detector; the penumbra forms at the edge of the shadow.</desc><rect x="82" y="105" width="16" height="30" rx="0" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="90" y="91" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">focal spot</text><rect x="264" y="70" width="12" height="50" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-muted,#6b7280);stroke-linecap:round;stroke-linejoin:round"/><line x1="370" y1="30" x2="370" y2="250" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="370" y="22" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">detector</text><line x1="90" y1="105" x2="370" y2="128.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:4 3"/><line x1="90" y1="135" x2="370" y2="111.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:4 3"/><line x1="376" y1="111.7" x2="376" y2="128.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="382" y="120" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">penumbra</text><text x="270" y="60" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">object</text><text x="90" y="151" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.80 mm</text><polygon points="90,270 96.3,267 96.3,273" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="94.9" y1="270" x2="265.1" y2="270" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="270,270 263.7,273 263.7,267" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="180" y="282" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.2 m</text><polygon points="270,270 276.3,267 276.3,273" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="274.9" y1="270" x2="365.1" y2="270" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="370,270 363.7,273 363.7,267" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="320" y="282" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.30 m</text></svg>', 'A focal spot 0.80 mm wide 1.2 m from an object, which is 0.30 m from the detector; the penumbra forms at the edge of the shadow.'),
('c08d5f3d-aeaf-5458-9b8f-5be9c88181ab', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 25, 25, 'A focal spot is 0.60 mm wide and the object–detector distance is 0.15 m. What is the smallest source–object distance that keeps the penumbra below 0.20 mm?', NULL, 2, 'numeric'::answer_type, '0.45', 'm', false, NULL, false, NULL, 'd = 0.60 × 0.15 ÷ 0.20 = 0.45 m. Mark scheme (4 marks). M1: w = s × (b/a). C1: rearranged. C1: value. A1: d = 0.45 m.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 460 300" role="img" aria-labelledby="fg1ef08c02-t fg1ef08c02-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg1ef08c02-t">Choosing the source distance</title><desc id="fg1ef08c02-d">A focal spot 0.60 mm wide, an object at an unknown distance d from the spot, and a detector 0.15 m beyond the object.</desc><rect x="82" y="105" width="16" height="30" rx="0" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="90" y="91" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">focal spot</text><rect x="264" y="70" width="12" height="50" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-muted,#6b7280);stroke-linecap:round;stroke-linejoin:round"/><line x1="370" y1="30" x2="370" y2="250" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="370" y="22" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">detector</text><line x1="90" y1="105" x2="370" y2="128.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:4 3"/><line x1="90" y1="135" x2="370" y2="111.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:4 3"/><line x1="376" y1="111.7" x2="376" y2="128.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="382" y="120" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">penumbra</text><text x="270" y="60" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">object</text><text x="90" y="151" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.60 mm</text><polygon points="90,270 96.3,267 96.3,273" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="94.9" y1="270" x2="265.1" y2="270" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="270,270 263.7,273 263.7,267" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="180" y="282" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">d</text><polygon points="270,270 276.3,267 276.3,273" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="274.9" y1="270" x2="365.1" y2="270" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="370,270 363.7,273 363.7,267" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="320" y="282" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.15 m</text></svg>', 'A focal spot 0.60 mm wide, an object at an unknown distance d from the spot, and a detector 0.15 m beyond the object.'),
('9bbf3ea4-cbfd-5037-a9be-0877123f7deb', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 26, 26, 'A beam crosses 1.0 cm of bone (μ = 0.60 cm⁻¹) on one path and 1.0 cm of soft tissue (μ = 0.20 cm⁻¹) on another. Calculate (transmitted intensity through tissue) ÷ (through bone).', NULL, 2, 'numeric'::answer_type, '1.492', NULL, false, NULL, false, NULL, 'Ratio = e^(−0.20) ÷ e^(−0.60) = e^(0.40) = 1.49. Mark scheme (3 marks). C1: transmitted fractions. C1: ratio. A1: ratio = 1.49.', 3, NULL, NULL),
('f96f6259-f9ce-5e29-a472-0719332d2493', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 27, 27, 'The tube voltage is lowered for a soft-tissue X-ray (such as mammography). Why?', NULL, 2, 'multiple_choice'::answer_type, 'Lower-energy photons give a bigger difference in attenuation between similar tissues, improving contrast', NULL, false, NULL, false, NULL, 'The difference in μ between soft tissues is larger at low energies. Mark scheme (3 marks). C1: larger μ difference. C1: better contrast. A1: C (Lower-energy photons give a bigger difference in attenuation between similar tissues, improving contrast).', 3, NULL, NULL),
('999934dc-7dc5-5eb4-93b9-59204d78ca1e', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 28, 28, 'A patient is moved from 1.0 m to 1.5 m from the tube. Assuming an inverse-square law, what fraction of the original intensity now reaches the patient?', NULL, 2, 'numeric'::answer_type, '0.4444', NULL, false, NULL, false, NULL, 'Fraction = (1.0 ÷ 1.5)² = 0.444. Mark scheme (3 marks). C1: I ∝ 1/d². C1: value. A1: fraction = 0.444.', 3, NULL, NULL),
('c627e651-208e-5bd3-9a6d-e92c6d2102c1', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 29, 29, 'Before a grid, the scattered intensity equals the primary intensity. The grid transmits 90% of the primary and 10% of the scatter. Calculate (scattered intensity ÷ primary intensity) after the grid.', NULL, 2, 'numeric'::answer_type, '0.1111', NULL, false, NULL, false, NULL, 'Ratio = 0.10 ÷ 0.90 = 0.111. Mark scheme (3 marks). C1: both transmissions. C1: ratio. A1: ratio = 0.111.', 3, NULL, NULL),
('adfa576f-be32-5d4c-8f56-e4f53ec6bf0d', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 30, 30, 'Why is barium sulfate given as a meal before an X-ray of the digestive tract?', NULL, 2, 'multiple_choice'::answer_type, 'It coats the gut wall and absorbs X-rays strongly, so the gut outline shows clearly', NULL, false, NULL, false, NULL, 'Barium has a high proton number. Mark scheme (3 marks). C1: high Z absorber. C1: outlines soft tissue. A1: A (It coats the gut wall and absorbs X-rays strongly, so the gut outline shows clearly).', 3, NULL, NULL),
('3c30f3cf-2076-5b8c-8529-03a829332a93', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 31, 31, 'Each 40 keV X-ray photon absorbed by an intensifying screen produces light photons of 2.5 eV, with 15% of the X-ray energy becoming light. How many light photons are produced per X-ray photon?', NULL, 2, 'numeric'::answer_type, '2400', NULL, false, NULL, false, NULL, 'N = 0.15 × 40 × 10³ ÷ 2.5 = 2400. Mark scheme (3 marks). C1: light energy. C1: ÷ photon energy. A1: N = 2400.', 3, NULL, NULL),
('7dd2e310-7275-5aa2-b31c-8a85b1f1d164', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 32, 32, 'A screen reduces the exposure time by a factor of 30, and moving the detector from 1.0 m to 1.2 m from the tube increases it by the inverse-square factor. Without either change the exposure was 0.60 s. Calculate the new exposure time.', NULL, 2, 'numeric'::answer_type, '0.0288', 's', false, NULL, false, NULL, 't = 0.60 ÷ 30 × (1.2 ÷ 1.0)² = 0.0288 s. Mark scheme (4 marks). C1: screen factor. C1: inverse-square factor. C1: combined. A1: t = 0.0288 s.', 4, NULL, NULL),
('b17c7888-3707-5120-a2fe-ab01ea98a5d9', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 33, 33, 'Why can the focal spot of an X-ray tube not simply be made as small as possible?', NULL, 2, 'multiple_choice'::answer_type, 'The heat from the electron beam would be concentrated on a tiny area and damage the target', NULL, false, NULL, false, NULL, 'Smaller spots improve sharpness but raise the heat per unit area. Mark scheme (3 marks). C1: heating. C1: trade-off with sharpness. A1: D (The heat from the electron beam would be concentrated on a tiny area and damage the target).', 3, NULL, NULL),
('aebd1f06-a973-54ae-9c16-1da854a7773a', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 34, 34, 'An exposure of 40 mA s gives a dose of 0.80 mGy. Assuming dose is proportional to mA s, calculate the dose for 25 mA s, in mGy.', NULL, 2, 'numeric'::answer_type, '0.5', 'mGy', false, NULL, false, NULL, 'D = 0.80 × 25 ÷ 40 = 0.50 mGy. Mark scheme (3 marks). C1: proportional. C1: value. A1: D = 0.50 mGy.', 3, NULL, NULL),
('8580b35e-0e63-529e-ab48-73c025b0c9f1', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 35, 35, 'An object is 0.20 m from the detector and the detector is 1.0 m from the focal spot. Calculate the magnification of its shadow.', NULL, 2, 'numeric'::answer_type, '1.25', NULL, false, NULL, false, NULL, 'M = (source–detector) ÷ (source–object) = 1.0 ÷ 0.80 = 1.25. Mark scheme (3 marks). C1: source–object = 0.80 m. C1: ratio. A1: M = 1.25.', 3, NULL, NULL),
('0a219fb0-21ea-51a1-b706-f890b93f6fd6', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 36, 36, 'What is the purpose of the lead strips in an anti-scatter grid?', NULL, 2, 'multiple_choice'::answer_type, 'To absorb X-rays travelling at an angle to the primary beam', NULL, false, NULL, false, NULL, 'Scattered photons hit the strips; primary photons pass between them. Mark scheme (3 marks). C1: angled photons absorbed. C1: primary passes. A1: B (To absorb X-rays travelling at an angle to the primary beam).', 3, NULL, NULL),
('0e67555d-fa68-5ab2-a0ea-bdfd7f343385', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 37, 37, 'A detector has pixels 0.10 mm wide. One line pair (one dark and one light line) needs at least two pixels. What is the finest resolution in line pairs per mm?', NULL, 2, 'numeric'::answer_type, '5', 'line pairs per mm', false, NULL, false, NULL, 'Resolution = 1 ÷ (2 × 0.10) = 5.0 line pairs per mm. Mark scheme (3 marks). C1: two pixels per line pair. C1: value. A1: resolution = 5.0 line pairs per mm.', 3, NULL, NULL),
('d01c6f3c-b731-585a-b32d-8d65effef1bc', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 38, 38, 'Behind two regions of an image the intensities are 150 and 50 units. Calculate the contrast, defined as (I₁ − I₂) ÷ (I₁ + I₂).', NULL, 2, 'numeric'::answer_type, '0.5', NULL, false, NULL, false, NULL, 'C = (150 − 50) ÷ (150 + 50) = 0.50. Mark scheme (3 marks). C1: substitution. C1: value. A1: contrast = 0.50.', 3, NULL, NULL),
('a27b3df1-f914-57be-a0d3-f1d0b042ea9d', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 39, 39, 'Why is an iodine compound injected to show blood vessels on an X-ray image?', NULL, 2, 'multiple_choice'::answer_type, 'Iodine has a high proton number, so the blood containing it absorbs X-rays strongly', NULL, false, NULL, false, NULL, 'Iodine fills the vessels and outlines them. Mark scheme (3 marks). C1: high Z. C1: vessels outlined. A1: C (Iodine has a high proton number, so the blood containing it absorbs X-rays strongly).', 3, NULL, NULL),
('633407f0-9e8c-5a16-9ad1-606868adab92', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 40, 40, 'The detector is moved from 1.0 m to 1.2 m from the tube. By what factor must the exposure time increase to keep the same detector intensity?', NULL, 2, 'numeric'::answer_type, '1.44', NULL, false, NULL, false, NULL, 'Factor = (1.2 ÷ 1.0)² = 1.44. Mark scheme (3 marks). C1: inverse square. C1: value. A1: factor = 1.44.', 3, NULL, NULL),
('319283df-ea42-5e95-b03f-6447ed32816b', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 41, 41, 'A focal spot is 1.2 mm wide. An object is 0.70 m from the spot and 0.30 m from the detector. Calculate the penumbra width in mm.', NULL, 2, 'numeric'::answer_type, '0.5143 mm', 'mm', false, NULL, false, NULL, 'w = 1.2 × 0.30 ÷ 0.70 = 0.514 mm. Mark scheme (4 marks). M1: similar triangles. C1: distances. C1: value. A1: w = 0.514 mm.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 460 300" role="img" aria-labelledby="fg68e66a99-t fg68e66a99-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg68e66a99-t">Penumbra</title><desc id="fg68e66a99-d">A focal spot 1.2 mm wide, an object 0.70 m from the spot and 0.30 m from the detector, and the penumbra at the edge of its shadow.</desc><rect x="82" y="105" width="16" height="30" rx="0" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="90" y="91" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">focal spot</text><rect x="264" y="70" width="12" height="50" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-muted,#6b7280);stroke-linecap:round;stroke-linejoin:round"/><line x1="370" y1="30" x2="370" y2="250" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="370" y="22" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">detector</text><line x1="90" y1="105" x2="370" y2="128.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:4 3"/><line x1="90" y1="135" x2="370" y2="111.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:4 3"/><line x1="376" y1="111.7" x2="376" y2="128.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="382" y="120" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">penumbra</text><text x="270" y="60" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">object</text><text x="90" y="151" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.2 mm</text><polygon points="90,270 96.3,267 96.3,273" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="94.9" y1="270" x2="265.1" y2="270" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="270,270 263.7,273 263.7,267" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="180" y="282" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.70 m</text><polygon points="270,270 276.3,267 276.3,273" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="274.9" y1="270" x2="365.1" y2="270" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="370,270 363.7,273 363.7,267" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="320" y="282" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.30 m</text></svg>', 'A focal spot 1.2 mm wide, an object 0.70 m from the spot and 0.30 m from the detector, and the penumbra at the edge of its shadow.'),
('78c108a6-12e5-52ff-85e2-5eeec5351d53', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 42, 42, 'How does an anti-scatter grid affect the exposure that must be given?', NULL, 2, 'multiple_choice'::answer_type, 'The exposure must be increased, because the grid also absorbs some of the primary beam', NULL, false, NULL, false, NULL, 'Better contrast comes at the cost of a larger dose. Mark scheme (3 marks). C1: grid absorbs some primary. C1: more exposure needed. A1: A (The exposure must be increased, because the grid also absorbs some of the primary beam).', 3, NULL, NULL),
('b7cf8945-c484-5901-b8a7-dfc41cbf9681', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 43, 43, 'A focal spot is 1.5 mm wide. A patient''s bone is 0.80 m from the spot and 0.20 m from the detector. (a) Calculate the magnification. (b) Calculate the penumbra width, in mm.', NULL, 3, 'numeric'::answer_type, '0.375 mm', 'mm', false, NULL, false, NULL, '(a) M = 1.00 ÷ 0.80 = 1.25. (b) w = 1.5 × 0.20 ÷ 0.80 = 0.375 mm. Mark scheme (5 marks). C1: source–detector distance. C1: magnification. M1: penumbra formula. C1: value. A1: w = 0.375 mm.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 460 300" role="img" aria-labelledby="fg31f577fb-t fg31f577fb-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg31f577fb-t">Magnification and penumbra</title><desc id="fg31f577fb-d">A focal spot 1.5 mm wide, a bone 0.80 m from the spot and 0.20 m from the detector, with the penumbra at the edge of its shadow.</desc><rect x="82" y="105" width="16" height="30" rx="0" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="90" y="91" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">focal spot</text><rect x="264" y="70" width="12" height="50" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-muted,#6b7280);stroke-linecap:round;stroke-linejoin:round"/><line x1="370" y1="30" x2="370" y2="250" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="370" y="22" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">detector</text><line x1="90" y1="105" x2="370" y2="128.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:4 3"/><line x1="90" y1="135" x2="370" y2="111.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:4 3"/><line x1="376" y1="111.7" x2="376" y2="128.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="382" y="120" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">penumbra</text><text x="270" y="60" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">object</text><text x="90" y="151" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.5 mm</text><polygon points="90,270 96.3,267 96.3,273" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="94.9" y1="270" x2="265.1" y2="270" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="270,270 263.7,273 263.7,267" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="180" y="282" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.80 m</text><polygon points="270,270 276.3,267 276.3,273" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="274.9" y1="270" x2="365.1" y2="270" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="370,270 363.7,273 363.7,267" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="320" y="282" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.20 m</text></svg>', 'A focal spot 1.5 mm wide, a bone 0.80 m from the spot and 0.20 m from the detector, with the penumbra at the edge of its shadow.'),
('77bb8b3c-d229-5f18-b042-176296d2ff84', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 44, 44, 'A beam of intensity I₀ reaches a limb. Path A crosses 8.0 cm of tissue (μ = 0.20 cm⁻¹); path B crosses 6.0 cm of tissue and 2.0 cm of bone (μ = 0.55 cm⁻¹). (a) Calculate the fraction transmitted on each path. (b) Calculate the contrast (I_A − I_B) ÷ (I_A + I_B).', NULL, 3, 'numeric'::answer_type, '0.3364', NULL, false, NULL, false, NULL, '(a) A: e^(−1.6) = 0.2019; B: e^(−1.2 − 1.1) = 0.1003. (b) (0.2019 − 0.1003) ÷ (0.2019 + 0.1003) = 0.336. Mark scheme (6 marks). C1: path A. C1: path B. M1: contrast formula. C1: substitution. C1: value. A1: contrast = 0.336.', 6, NULL, NULL),
('353d71a2-ae08-54ec-8929-cd51f16dbed4', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 45, 45, 'An exposure at 1.0 m without screens takes 1.2 s. It is repeated at 1.5 m using screens that reduce the exposure by a factor of 20. (a) Calculate the inverse-square factor. (b) Calculate the new exposure time.', NULL, 3, 'numeric'::answer_type, '0.135', 's', false, NULL, false, NULL, '(a) (1.5 ÷ 1.0)² = 2.25. (b) t = 1.2 × 2.25 ÷ 20 = 0.135 s. Mark scheme (5 marks). C1: inverse-square factor. C1: screen factor. M1: combine. C1: value. A1: t = 0.135 s.', 5, NULL, NULL),
('ba2fecb5-e189-569b-abb4-03baa0afd4ff', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 46, 46, 'Without a grid, 60% of the photons reaching the detector are scattered. A grid transmits 75% of the primary photons and 8.0% of the scattered photons. (a) Calculate the fraction of primary photons before the grid. (b) Calculate the fraction of the photons reaching the detector that are scattered once the grid is used. Give only the answer to (b), as a percentage.', NULL, 3, 'numeric'::answer_type, '13.79', '%', false, NULL, false, NULL, '(a) 1 − 0.60 = 0.40. (b) Scatter: 0.60 × 0.080 = 0.048; primary: 0.40 × 0.75 = 0.30. Percentage = 0.048 ÷ (0.048 + 0.30) × 100 = 13.8 %. Mark scheme (6 marks). C1: primary fraction. C1: scatter after grid. C1: primary after grid. M1: ratio. C1: value. A1: percentage = 13.8%.', 6, NULL, NULL),
('f1f28b07-5f48-54f7-9780-d37c52666424', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 47, 47, 'Blood vessels filled with iodine contrast (μ = 4.0 cm⁻¹) are 0.30 cm across and surrounded by tissue (μ = 0.20 cm⁻¹). (a) Calculate the transmitted fraction across 0.30 cm of vessel. (b) Calculate it across 0.30 cm of tissue. (c) Calculate (tissue fraction) ÷ (vessel fraction). Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '3.127', NULL, false, NULL, false, NULL, '(a) e^(−4.0 × 0.30) = 0.3012. (b) e^(−0.20 × 0.30) = 0.9418. (c) 0.9418 ÷ 0.3012 = 3.13. Mark scheme (5 marks). C1: vessel. C1: tissue. M1: ratio. C1: value. A1: ratio = 3.13.', 5, NULL, NULL),
('77450301-8ad6-5a88-8c2a-7a3502c791e5', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 48, 48, 'An X-ray beam has an intensity of 6.0 W m⁻² at 1.0 m from the focal spot. A patient 20 cm thick (μ = 0.20 cm⁻¹) lies with the far side 1.6 m from the spot. (a) Calculate the intensity at 1.6 m without the patient. (b) Calculate the intensity reaching the detector behind the patient.', NULL, 3, 'numeric'::answer_type, '0.04293', 'W m⁻²', false, NULL, false, NULL, '(a) I = 6.0 × (1.0 ÷ 1.6)² = 2.344 W m⁻². (b) I = 2.344 × e^(−0.20 × 20) = 0.0429 W m⁻². Mark scheme (6 marks). C1: inverse square. C1: value. C1: μx = 4.0. M1: multiply. C1: value. A1: I = 0.0429 W m⁻².', 6, NULL, NULL),
('02680295-9c3a-5022-b9e3-e93e0e885c37', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 49, 49, 'An intensifying screen absorbs 30% of the 50 keV X-ray photons reaching it, and converts 12% of the absorbed energy into light photons of 2.4 eV. (a) Calculate the light energy per absorbed X-ray photon in eV. (b) Calculate the number of light photons produced per incident X-ray photon.', NULL, 3, 'numeric'::answer_type, '750', NULL, false, NULL, false, NULL, '(a) 0.12 × 50 × 10³ = 6000 eV. (b) N = 0.30 × 6000 ÷ 2.4 = 750. Mark scheme (5 marks). C1: light energy. M1: × 0.30. C1: ÷ 2.4 eV. C1: value. A1: N = 750.', 5, NULL, NULL),
('31a6ff7a-7378-5bb9-bf71-427cb7c6920e', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', '3029b74c-e574-49c0-b55c-05e9699dc0bb', 'a-level', '30.3', '9702 coursebook 30.3 · Improving X-ray images', 50, 50, 'A digital detector has 3000 × 3000 pixels, each storing a 14-bit value. (a) Calculate the number of pixels. (b) Calculate the image size in bits. (c) Calculate the image size in megabytes (MB), taking 1 byte = 8 bits and 1 MB = 10⁶ bytes. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '15.75', 'MB', false, NULL, false, NULL, '(a) 3000 × 3000 = 9.0 × 10⁶. (b) 9.0 × 10⁶ × 14 = 1.26 × 10⁸ bits. (c) 1.26 × 10⁸ ÷ 8 ÷ 10⁶ = 15.8 MB. Mark scheme (6 marks). C1: pixels. C1: bits. M1: ÷ 8 for bytes. C1: ÷ 10⁶ for MB. C1: value. A1: size = 15.8 MB.', 6, NULL, NULL)
