('5d1e9965-f6d6-5829-9034-75a76e458175', '5b79cd56-4920-5d93-9e42-a34bcfe65121', 'Touching the X-ray tube', 'D', false, 3),
('2b535599-f8c7-52da-a867-f480e1ea5626', 'f96f6259-f9ce-5e29-a472-0719332d2493', 'Lower voltage reduces the dose', 'A', false, 0),
('b74cc87a-320b-578c-b67f-75bad69c9baa', 'f96f6259-f9ce-5e29-a472-0719332d2493', 'Lower-energy photons pass straight through', 'B', false, 1),
('57b1dc10-45d9-5ccc-99d0-5404c2797c1a', 'f96f6259-f9ce-5e29-a472-0719332d2493', 'Lower-energy photons give a bigger difference in attenuation between similar tissues, improving contrast', 'C', true, 2),
('c760d57b-6869-5ae9-9ead-8470a168ebd9', 'f96f6259-f9ce-5e29-a472-0719332d2493', 'It makes the image sharper', 'D', false, 3),
('0a79cb59-dcb8-5b5b-aa7b-d90ef5bf0f77', 'adfa576f-be32-5d4c-8f56-e4f53ec6bf0d', 'It coats the gut wall and absorbs X-rays strongly, so the gut outline shows clearly', 'A', true, 0),
('7e6bae75-e9be-5e1a-85ab-3469e7a35fe3', 'adfa576f-be32-5d4c-8f56-e4f53ec6bf0d', 'It makes the gut transparent to X-rays', 'B', false, 1),
('1c65c4ea-a29f-56c5-8254-32ae0c401c92', 'adfa576f-be32-5d4c-8f56-e4f53ec6bf0d', 'It reduces the X-ray dose', 'C', false, 2),
('937955db-8603-5e08-9f20-eb72eaaef707', 'adfa576f-be32-5d4c-8f56-e4f53ec6bf0d', 'It is radioactive and emits X-rays', 'D', false, 3),
('21367c74-abb7-54a5-8374-be65a7dd8d58', 'b17c7888-3707-5120-a2fe-ab01ea98a5d9', 'A small spot gives no X-rays', 'A', false, 0),
('2cc20468-a569-5ae2-ae39-4832abb43bd4', 'b17c7888-3707-5120-a2fe-ab01ea98a5d9', 'A small spot gives a blurred image', 'B', false, 1),
('a9362aba-db9a-5c5f-b3e3-1e09f06fd982', 'b17c7888-3707-5120-a2fe-ab01ea98a5d9', 'A small spot reduces contrast', 'C', false, 2),
('5b7cf615-f976-54f6-9919-b0f101e07243', 'b17c7888-3707-5120-a2fe-ab01ea98a5d9', 'The heat from the electron beam would be concentrated on a tiny area and damage the target', 'D', true, 3),
('fdc37805-c19d-5716-9f6f-1f2e7a48ff5d', '0a219fb0-21ea-51a1-b706-f890b93f6fd6', 'To absorb the primary beam', 'A', false, 0),
('15a2de9f-6b63-5c05-af35-00df72595289', '0a219fb0-21ea-51a1-b706-f890b93f6fd6', 'To absorb X-rays travelling at an angle to the primary beam', 'B', true, 1),
('062e17c7-64e2-5c1a-960d-5a5a901f0768', '0a219fb0-21ea-51a1-b706-f890b93f6fd6', 'To focus the X-rays', 'C', false, 2),
('ba22aaf2-74ed-503a-8937-de2b9880007d', '0a219fb0-21ea-51a1-b706-f890b93f6fd6', 'To produce light', 'D', false, 3),
('00bfb88f-b328-50fc-bff6-2a4d6ad1bd8d', 'a27b3df1-f914-57be-a0d3-f1d0b042ea9d', 'Iodine reduces blood flow', 'A', false, 0),
('a46f3c3a-a852-5dd4-bbfe-6a61cf78887a', 'a27b3df1-f914-57be-a0d3-f1d0b042ea9d', 'Iodine makes the vessels wider', 'B', false, 1),
('b54d0a3f-7e2c-5292-b980-fe4cb979f46a', 'a27b3df1-f914-57be-a0d3-f1d0b042ea9d', 'Iodine has a high proton number, so the blood containing it absorbs X-rays strongly', 'C', true, 2),
('b24df132-bd03-5857-bc66-4228f8e1255a', 'a27b3df1-f914-57be-a0d3-f1d0b042ea9d', 'Iodine is a gas that shows up as a shadow', 'D', false, 3),
('dc66243b-1197-5354-b124-51fe2fbcf024', '78c108a6-12e5-52ff-85e2-5eeec5351d53', 'The exposure must be increased, because the grid also absorbs some of the primary beam', 'A', true, 0),
('7ad62c90-8540-5876-af8c-7706d003fe75', '78c108a6-12e5-52ff-85e2-5eeec5351d53', 'The exposure can be reduced', 'B', false, 1),
('d4d85514-7d6e-563e-915f-36692746d12a', '78c108a6-12e5-52ff-85e2-5eeec5351d53', 'The exposure is unchanged', 'C', false, 2),
('ad0da78c-1ebe-57a4-909f-a6c31efc983b', '78c108a6-12e5-52ff-85e2-5eeec5351d53', 'The exposure must be halved', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('ba738066-7b48-5126-9e29-82dd89a508cb', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'b4831698-a4b4-443d-99d1-518973eaa5a7', 'a-level', '30.4', '9702 coursebook 30.4 · Computerised axial tomography', 7, 7, 'A CT slice is reconstructed as 512 × 512 pixels. How many pixels does the slice contain?', NULL, 1, 'numeric'::answer_type, '2.621e5', NULL, false, NULL, false, NULL, 'N = 512 × 512 = 262 144 pixels. Mark scheme (2 marks). C1: rows × columns. A1: N = 2.62144 × 10⁵.', 2, NULL, NULL),
('a74dc9c7-1ab7-5c75-ae04-cf1326536f1c', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'b4831698-a4b4-443d-99d1-518973eaa5a7', 'a-level', '30.4', '9702 coursebook 30.4 · Computerised axial tomography', 8, 8, 'In a 2 × 2 block of voxels, the left column reads 7 and its top voxel has a value of 3. What is the value of its bottom voxel?', NULL, 1, 'numeric'::answer_type, '4', NULL, false, NULL, false, NULL, 'Column reading = sum of its voxels: bottom = 7 − 3 = 4. Mark scheme (2 marks). C1: readings are sums. A1: value = 4.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 290" role="img" aria-labelledby="fgb5ba895d-t fgb5ba895d-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgb5ba895d-t">Column reading</title><desc id="fgb5ba895d-d">A 2 × 2 block of voxels; the beam down the left column gives a reading of 7 and the top-left voxel has the value 3.</desc><rect x="110" y="60" width="80" height="80" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="150" y="100" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">3</text><rect x="190" y="60" width="80" height="80" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="110" y="140" width="80" height="80" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="150" y="180" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">?</text><rect x="190" y="140" width="80" height="80" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="30" y1="100" x2="99.8" y2="100" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="104,100 98.6,102.5 98.6,97.5" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="30" y1="180" x2="99.8" y2="180" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="104,180 98.6,182.5 98.6,177.5" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="150" y1="18" x2="150" y2="49.8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="150,54 147.5,48.6 152.5,48.6" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="150" y="242" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">7</text><line x1="230" y1="18" x2="230" y2="49.8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="230,54 227.5,48.6 232.5,48.6" style="fill:var(--fig-accent-2,#b45309);stroke:none"/></svg>', 'A 2 × 2 block of voxels; the beam down the left column gives a reading of 7 and the top-left voxel has the value 3.'),
('c6fdab12-1df1-561b-b682-d6d282f24a96', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'b4831698-a4b4-443d-99d1-518973eaa5a7', 'a-level', '30.4', '9702 coursebook 30.4 · Computerised axial tomography', 9, 9, 'A CT data set is 256 × 256 pixels in each of 50 slices. How many voxels does it contain?', NULL, 1, 'numeric'::answer_type, '3.277e6', NULL, false, NULL, false, NULL, 'N = 256 × 256 × 50 = 3 276 800, about 3.28 × 10⁶. Mark scheme (2 marks). C1: multiply the three numbers. A1: N = 3.28 × 10⁶.', 2, NULL, NULL),
('1de9be21-e804-5d26-8a9a-e01697c33f98', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'b4831698-a4b4-443d-99d1-518973eaa5a7', 'a-level', '30.4', '9702 coursebook 30.4 · Computerised axial tomography', 10, 10, 'What is a voxel in a CT scan?', NULL, 1, 'multiple_choice'::answer_type, 'A small volume element of the patient whose attenuation is calculated', NULL, false, NULL, false, NULL, 'CT computes a value for each voxel, which is shown as a pixel in a slice. Mark scheme (1 mark). B1: C (A small volume element of the patient whose attenuation is calculated).', 1, NULL, NULL),
('397cf449-a1de-522e-aa69-9b1b0872d275', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'b4831698-a4b4-443d-99d1-518973eaa5a7', 'a-level', '30.4', '9702 coursebook 30.4 · Computerised axial tomography', 11, 11, 'A CT scan covers 120 mm of a patient in 40 equal slices. Calculate the thickness of each slice in mm.', NULL, 1, 'numeric'::answer_type, '3 mm', 'mm', false, NULL, false, NULL, 't = 120 ÷ 40 = 3.0 mm. Mark scheme (2 marks). C1: length ÷ number. A1: t = 3.0 mm.', 2, NULL, NULL),
('5174e1a8-5250-511f-adf1-52fd7afacf47', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'b4831698-a4b4-443d-99d1-518973eaa5a7', 'a-level', '30.4', '9702 coursebook 30.4 · Computerised axial tomography', 12, 12, 'How does the X-ray source move during a CT scan?', NULL, 1, 'multiple_choice'::answer_type, 'It rotates around the patient', NULL, false, NULL, false, NULL, 'Projections are needed from many angles. Mark scheme (1 mark). B1: A (It rotates around the patient).', 1, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 320" role="img" aria-labelledby="fgc79383e2-t fgc79383e2-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgc79383e2-t">CT scanner</title><desc id="fgc79383e2-d">End-on view of a CT scanner showing the X-ray tube, the patient and an arc of detectors on the opposite side, with the direction of rotation.</desc><circle cx="180" cy="160" r="120" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:5 4"/><circle cx="180" cy="160" r="48" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="180" y="160" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">patient</text><rect x="160" y="28" width="40" height="24" rx="4" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="208" y="28" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">X-ray tube</text><rect x="108.9" y="255.5" width="8" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="116" y="259.9" width="8" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="123.4" y="263.9" width="8" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="131" y="267.3" width="8" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="138.9" y="270.1" width="8" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="147" y="272.4" width="8" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="155.2" y="274.2" width="8" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="163.5" y="275.3" width="8" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="171.8" y="275.9" width="8" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="180.2" y="275.9" width="8" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="188.5" y="275.3" width="8" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="196.8" y="274.2" width="8" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="205" y="272.4" width="8" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="213.1" y="270.1" width="8" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="221" y="267.3" width="8" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="228.6" y="263.9" width="8" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="236" y="259.9" width="8" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="243.1" y="255.5" width="8" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="180" y1="52" x2="112.9" y2="255.5" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="180" y1="52" x2="180" y2="276" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="180" y1="52" x2="247.1" y2="255.5" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="250" y="276" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">detector arc</text><path d="M114,45.7 A132,132 0 0,0 56,114.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="56,114.9 55.3,106.9 61.6,109.2" style="fill:var(--fig-muted,#6b7280);stroke:none"/></svg>', 'End-on view of a CT scanner showing the X-ray tube, the patient and an arc of detectors on the opposite side, with the direction of rotation.'),
('790eb12e-cdd9-557a-83c9-59f536a93ba3', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'b4831698-a4b4-443d-99d1-518973eaa5a7', 'a-level', '30.4', '9702 coursebook 30.4 · Computerised axial tomography', 13, 13, 'A CT image is 512 pixels across and represents a width of 250 mm. Calculate the width of one pixel in mm.', NULL, 1, 'numeric'::answer_type, '0.4883 mm', 'mm', false, NULL, false, NULL, 'w = 250 ÷ 512 = 0.488 mm. Mark scheme (2 marks). C1: width ÷ pixels. A1: w = 0.488 mm.', 2, NULL, NULL),
('a85bc242-5b50-56a0-a33c-8b0621924b56', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'b4831698-a4b4-443d-99d1-518973eaa5a7', 'a-level', '30.4', '9702 coursebook 30.4 · Computerised axial tomography', 14, 14, 'What does each detector reading in a CT scanner measure?', NULL, 1, 'multiple_choice'::answer_type, 'The total attenuation along one path through the patient', NULL, false, NULL, false, NULL, 'The computer works out individual voxel values from many such sums. Mark scheme (1 mark). B1: D (The total attenuation along one path through the patient).', 1, NULL, NULL),
('4a47d0b5-594e-5aa7-b1f9-6f7d02a705a4', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'b4831698-a4b4-443d-99d1-518973eaa5a7', 'a-level', '30.4', '9702 coursebook 30.4 · Computerised axial tomography', 15, 15, 'The diagram shows a 2 × 2 block of voxels. The detector reading along the top row is 9, and the left voxel of that row has a value of 4. What is the value of the right voxel of the top row?', NULL, 1, 'numeric'::answer_type, '5', NULL, false, NULL, false, NULL, 'Row reading = sum of its voxels: right voxel = 9 − 4 = 5. Mark scheme (2 marks). C1: readings are sums. A1: value = 5.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 290" role="img" aria-labelledby="fg6b5205ef-t fg6b5205ef-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg6b5205ef-t">Voxel readings</title><desc id="fg6b5205ef-d">A 2 × 2 block of voxels. The beam along the top row gives a reading of 9; the top-left voxel has the value 4 and the other values are unknown.</desc><rect x="110" y="60" width="80" height="80" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="150" y="100" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4</text><rect x="190" y="60" width="80" height="80" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="230" y="100" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">?</text><rect x="110" y="140" width="80" height="80" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="190" y="140" width="80" height="80" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="30" y1="100" x2="99.8" y2="100" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="104,100 98.6,102.5 98.6,97.5" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="274" y1="100" x2="300" y2="100" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="306" y="100" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">9</text><line x1="30" y1="180" x2="99.8" y2="180" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="104,180 98.6,182.5 98.6,177.5" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="150" y1="18" x2="150" y2="49.8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="150,54 147.5,48.6 152.5,48.6" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="230" y1="18" x2="230" y2="49.8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="230,54 227.5,48.6 232.5,48.6" style="fill:var(--fig-accent-2,#b45309);stroke:none"/></svg>', 'A 2 × 2 block of voxels. The beam along the top row gives a reading of 9; the top-left voxel has the value 4 and the other values are unknown.'),
('4c5f674b-5c02-5b0b-9d1d-358cc78efada', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'b4831698-a4b4-443d-99d1-518973eaa5a7', 'a-level', '30.4', '9702 coursebook 30.4 · Computerised axial tomography', 16, 16, 'Why does a CT scan usually give a larger dose than a single radiograph?', NULL, 1, 'multiple_choice'::answer_type, 'Many X-ray projections are taken through the same region', NULL, false, NULL, false, NULL, 'Each slice needs projections from many angles. Mark scheme (1 mark). B1: B (Many X-ray projections are taken through the same region).', 1, NULL, NULL),
('ab55039c-1827-5ab6-bbbe-274f9900ddaf', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'b4831698-a4b4-443d-99d1-518973eaa5a7', 'a-level', '30.4', '9702 coursebook 30.4 · Computerised axial tomography', 17, 17, 'A CT scanner takes 0.50 s per rotation and makes 64 rotations. Calculate the scan time.', NULL, 1, 'numeric'::answer_type, '32', 's', false, NULL, false, NULL, 't = 0.50 × 64 = 32 s. Mark scheme (2 marks). C1: time per rotation × number. A1: t = 32 s.', 2, NULL, NULL),
('564ca8a0-1440-5154-8369-509083210478', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'b4831698-a4b4-443d-99d1-518973eaa5a7', 'a-level', '30.4', '9702 coursebook 30.4 · Computerised axial tomography', 18, 18, 'What is a key advantage of CT over a plain radiograph for soft tissue?', NULL, 1, 'multiple_choice'::answer_type, 'It can distinguish tissues whose attenuation coefficients differ only slightly', NULL, false, NULL, false, NULL, 'Computed values separate small differences in μ. Mark scheme (1 mark). B1: C (It can distinguish tissues whose attenuation coefficients differ only slightly).', 1, NULL, NULL),
('70e90e32-143f-53a3-ab0d-c7dd95c3e6df', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'b4831698-a4b4-443d-99d1-518973eaa5a7', 'a-level', '30.4', '9702 coursebook 30.4 · Computerised axial tomography', 19, 19, 'A CT scan gives an effective dose of 8.0 mSv and a chest radiograph 0.020 mSv. Calculate (CT dose) ÷ (radiograph dose).', NULL, 1, 'numeric'::answer_type, '400', NULL, false, NULL, false, NULL, 'Ratio = 8.0 ÷ 0.020 = 400. Mark scheme (2 marks). C1: ratio. A1: ratio = 400.', 2, NULL, NULL),
('3b77e415-f9b4-5e47-a52f-d29fbe137510', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'b4831698-a4b4-443d-99d1-518973eaa5a7', 'a-level', '30.4', '9702 coursebook 30.4 · Computerised axial tomography', 20, 20, 'How is the calculated attenuation of each voxel displayed in a CT image?', NULL, 1, 'multiple_choice'::answer_type, 'As a shade of grey in the corresponding pixel', NULL, false, NULL, false, NULL, 'Higher attenuation is usually shown lighter. Mark scheme (1 mark). B1: A (As a shade of grey in the corresponding pixel).', 1, NULL, NULL),
('621a5c8c-9051-5e20-b37a-20758b6f9087', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'b4831698-a4b4-443d-99d1-518973eaa5a7', 'a-level', '30.4', '9702 coursebook 30.4 · Computerised axial tomography', 21, 21, 'A CT scanner records projections every 1.0° through one full rotation. How many projections does it record per rotation?', NULL, 1, 'numeric'::answer_type, '360', NULL, false, NULL, false, NULL, 'One rotation is 360°, so N = 360 ÷ 1.0 = 360 projections. Mark scheme (2 marks). C1: 360° ÷ step. A1: N = 360.', 2, NULL, NULL),
('f7b07c3b-dc70-557a-977f-cd2b9eb57b44', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'b4831698-a4b4-443d-99d1-518973eaa5a7', 'a-level', '30.4', '9702 coursebook 30.4 · Computerised axial tomography', 22, 22, 'In a helical (spiral) CT scan, what happens during the scan?', NULL, 1, 'multiple_choice'::answer_type, 'The patient moves steadily through the rotating X-ray beam', NULL, false, NULL, false, NULL, 'The tube traces a helix relative to the patient. Mark scheme (1 mark). B1: D (The patient moves steadily through the rotating X-ray beam).', 1, NULL, NULL),
('5253462f-b017-5b6e-b562-712ce0bd46e6', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'b4831698-a4b4-443d-99d1-518973eaa5a7', 'a-level', '30.4', '9702 coursebook 30.4 · Computerised axial tomography', 23, 23, 'In a helical scan the table moves 40 mm in each 0.50 s rotation. Calculate the table speed in mm s⁻¹.', NULL, 1, 'numeric'::answer_type, '80', 'mm s⁻¹', false, NULL, false, NULL, 'v = 40 ÷ 0.50 = 80 mm s⁻¹. Mark scheme (2 marks). C1: distance ÷ time. A1: v = 80 mm s⁻¹.', 2, NULL, NULL),
('395d83eb-652b-5d4b-a606-040d111aaf96', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'b4831698-a4b4-443d-99d1-518973eaa5a7', 'a-level', '30.4', '9702 coursebook 30.4 · Computerised axial tomography', 24, 24, 'Why is CT especially useful for imaging the brain?', NULL, 1, 'multiple_choice'::answer_type, 'It shows small differences between soft tissues inside the skull', NULL, false, NULL, false, NULL, 'A plain radiograph would be dominated by the skull. Mark scheme (1 mark). B1: B (It shows small differences between soft tissues inside the skull).', 1, NULL, NULL),
('347c85af-1951-5ecf-ba32-595d4ade600f', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'b4831698-a4b4-443d-99d1-518973eaa5a7', 'a-level', '30.4', '9702 coursebook 30.4 · Computerised axial tomography', 25, 25, 'A CT slice is 512 × 512 pixels, each stored as 2 bytes. Calculate the size of one slice in bytes.', NULL, 1, 'numeric'::answer_type, '5.243e5', 'bytes', false, NULL, false, NULL, 'Size = 512 × 512 × 2 = 524 288 bytes. Mark scheme (1 mark). A1: size = 5.24288 × 10⁵ bytes.', 1, NULL, NULL),
('99c1f652-80d6-57a1-aa66-64ee5fb1dba3', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'b4831698-a4b4-443d-99d1-518973eaa5a7', 'a-level', '30.4', '9702 coursebook 30.4 · Computerised axial tomography', 26, 26, 'The diagram shows a 2 × 2 block of voxels with top row reading 7, bottom row 11, left column 8 and right column 10. A diagonal reading through the top-left and bottom-right voxels is 9. Find the value of the top-left voxel.', NULL, 2, 'numeric'::answer_type, '3', NULL, false, NULL, false, NULL, 'Let the top-left be a. Top-right = 7 − a, bottom-left = 8 − a, bottom-right = 9 − a. Bottom row: (8 − a) + (9 − a) = 11, so a = (17 − 11) ÷ 2 = 3. Mark scheme (3 marks). M1: express others in terms of a. C1: bottom-row equation. A1: a = 3.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 290" role="img" aria-labelledby="fg6dbae2fe-t fg6dbae2fe-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg6dbae2fe-t">Reconstructing a block</title><desc id="fg6dbae2fe-d">A 2 × 2 block of voxels with readings: top row 7, bottom row 11, left column 8, right column 10, and 9 along the diagonal from top-left to bottom-right.</desc><rect x="110" y="60" width="80" height="80" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="150" y="100" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">a</text><rect x="190" y="60" width="80" height="80" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="110" y="140" width="80" height="80" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="190" y="140" width="80" height="80" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="30" y1="100" x2="99.8" y2="100" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="104,100 98.6,102.5 98.6,97.5" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="274" y1="100" x2="300" y2="100" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="306" y="100" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">7</text><line x1="30" y1="180" x2="99.8" y2="180" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="104,180 98.6,182.5 98.6,177.5" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="274" y1="180" x2="300" y2="180" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="306" y="180" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">11</text><line x1="150" y1="18" x2="150" y2="49.8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="150,54 147.5,48.6 152.5,48.6" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="150" y="242" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">8</text><line x1="230" y1="18" x2="230" y2="49.8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="230,54 227.5,48.6 232.5,48.6" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="230" y="242" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">10</text><line x1="86" y1="36" x2="288" y2="238" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:4 3"/><text x="294" y="246" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">9</text></svg>', 'A 2 × 2 block of voxels with readings: top row 7, bottom row 11, left column 8, right column 10, and 9 along the diagonal from top-left to bottom-right.'),
('89219644-a460-5ea4-bcd2-9f929aab9fe0', '1fd2e146-9233-4bc7-8fd2-b600f61a7d73', 'b4831698-a4b4-443d-99d1-518973eaa5a7', 'a-level', '30.4', '9702 coursebook 30.4 · Computerised axial tomography', 27, 27, 'A 2 × 2 block of voxels has top row 10, bottom row 14, left column 9 and right column 15. The diagonal through the top-left and bottom-right voxels reads 13. Find the value of the bottom-right voxel.', NULL, 2, 'numeric'::answer_type, '9', NULL, false, NULL, false, NULL, 'Top-left a: top-right 10 − a, bottom-left 9 − a, bottom-right 13 − a. Bottom row: 22 − 2a = 14, so a = (22 − 14) ÷ 2 = 4; bottom-right = 13 − 4 = 9. Mark scheme (4 marks). M1: unknowns in terms of a. C1: solve for a. C1: bottom-right. A1: value = 9.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 290" role="img" aria-labelledby="fg8f01e0d9-t fg8f01e0d9-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg8f01e0d9-t">Reconstructing a block</title><desc id="fg8f01e0d9-d">A 2 × 2 block of voxels with readings: top row 10, bottom row 14, left column 9, right column 15, and 13 along the diagonal from top-left to bottom-right.</desc><rect x="110" y="60" width="80" height="80" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="190" y="60" width="80" height="80" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="110" y="140" width="80" height="80" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="190" y="140" width="80" height="80" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="230" y="180" font-size="14" text-ancho