('d551902c-fde2-5bcf-9d93-a6f2db0a6d70', 'f7b07c3b-dc70-557a-977f-cd2b9eb57b44', 'The patient moves steadily through the rotating X-ray beam', 'D', true, 3),
('5a75d44d-3fea-53ea-953b-2469d097efb3', '395d83eb-652b-5d4b-a606-040d111aaf96', 'X-rays cannot pass through the skull otherwise', 'A', false, 0),
('b01fd78d-25f8-5f1c-a5e3-8bdcdfc4aa30', '395d83eb-652b-5d4b-a606-040d111aaf96', 'It shows small differences between soft tissues inside the skull', 'B', true, 1),
